// Lieux de livraison habituels préenregistrés. À ceux-ci s'ajoutent automatiquement
// les adresses déjà saisies dans les commandes passées (voir usualDeliveryPlaces()).
const PRESET_DELIVERY_PLACES = [
  'Leclerc Sargé',
  'Intermarché Av Bollée',
  'Place des Jacobins',
  'Place de la République',
  'Carrefour Market Boulevard Mutuel',
  'Lidl Allonnes'
];
// Construit la liste dédupliquée des lieux à suggérer : presets + lieux déjà
// utilisés dans des commandes (les plus fréquents/récents d'abord), hors doublons.
// Autocomplete personnalisé pour le champ adresse (remplace le <datalist> natif,
// peu fiable sur iOS). Affiche les suggestions au focus et filtre à la frappe.
function acFilter(q){
  const list = document.getElementById('acList'); if(!list) return;
  const term = normTxt((q||'').trim());
  // 1) Adresses du carnet (avec distance/temps) — proposées en priorité.
  const book = (getSettings().addressBook||[]);
  const bookMatch = (term ? book.filter(a=>normTxt(a.libelle||'').includes(term)) : book).slice(0,6);
  // 2) Lieux issus des commandes passées / clients (simples chaînes).
  const all = window.__placesCache || [];
  const plainMatch = (term ? all.filter(p=>normTxt(p).includes(term)) : all).slice(0, 6);
  let html = '';
  if(bookMatch.length){
    html += bookMatch.map((a,i)=>{
      const bi = book.indexOf(a);
      const meta = [a.km!=null?a.km+' km':'', a.min!=null?a.min+' min':''].filter(Boolean).join(' · ');
      return `<div class="ac-item ac-book" onmousedown="acPickBook(${bi})">📍 <b>${esc(a.libelle)}</b>${meta?` <span class="ac-meta">${esc(meta)}</span>`:''}</div>`;
    }).join('');
  }
  if(plainMatch.length){
    html += plainMatch.map(p=>`<div class="ac-item" onmousedown="acPick(${JSON.stringify(p).replace(/"/g,'&quot;')})">${esc(p)}</div>`).join('');
  }
  if(!html){ list.style.display='none'; list.innerHTML=''; return; }
  list.innerHTML = html;
  list.style.display='block';
}
function acPick(val){
  const inp=document.getElementById('f_lieu'); if(inp){ inp.value=val; }
  const list=document.getElementById('acList'); if(list){ list.style.display='none'; }
}
// Choix d'une adresse du carnet : remplit le lieu ET pré-remplit distance + temps.
function acPickBook(bookIndex){
  const a = (getSettings().addressBook||[])[bookIndex]; if(!a) return;
  const inp=document.getElementById('f_lieu'); if(inp) inp.value=a.libelle||'';
  const km=document.getElementById('f_distKm'); if(km && a.km!=null) km.value=a.km;
  const min=document.getElementById('f_tempsLiv'); if(min && a.min!=null) min.value=a.min;
  const list=document.getElementById('acList'); if(list) list.style.display='none';
  // s'assurer que le bloc livraison est ouvert pour voir les valeurs pré-remplies
  const body=document.getElementById('livBody');
  if(body && body.style.display==='none' && typeof toggleLivBlock==='function') toggleLivBlock();
  if(typeof cmdDeliveryRecalc==='function') cmdDeliveryRecalc();
  toast(`Distance et temps pré-remplis pour « ${a.libelle} »`);
}
// Ferme la liste si on clique ailleurs.
document.addEventListener('click', e=>{
  const w=e.target.closest && e.target.closest('.ac-wrap');
  if(!w){ const l=document.getElementById('acList'); if(l) l.style.display='none'; }
});
async function usualDeliveryPlaces(){
  const [orders, clients] = await Promise.all([
    db.orders.toArray().catch(()=>[]),
    db.clients.toArray().catch(()=>[])
  ]);
  const freq = {};
  orders.forEach(o=>{
    const v = (o.lieuLivraison||'').trim();
    if(v) freq[v] = (freq[v]||0) + 1;
  });
  // lieux issus des commandes, triés par fréquence décroissante
  const fromOrders = Object.keys(freq).sort((a,b)=>freq[b]-freq[a]);
  // adresses enregistrées sur les fiches clients (nom + adresse pour faciliter la recherche)
  const fromClients = [];
  clients.forEach(c=>{
    const a=(c.adresse||'').trim(); if(!a) return;
    fromClients.push(a);
    if(c.nom) fromClients.push(`${c.nom} — ${a}`);
  });
  // fusion sans doublon (insensible à la casse), presets puis commandes puis clients
  const seen = new Set(), out = [];
  [...PRESET_DELIVERY_PLACES, ...fromOrders, ...fromClients].forEach(v=>{
    const k = v.toLowerCase();
    if(!seen.has(k)){ seen.add(k); out.push(v); }
  });
  return out;
}

// Prestation événement
const EVENT_PRICE = 1.60;       // prix par macaron
const EVENT_MIN = 35;           // quantité minimale
const EQUIP_PRICE = 20;         // location présentoir / pyramide (par unité)
const EVENT_MIN_EQUIP = 1;      // au moins 1 pyramide obligatoire
const PYRA_PRICE = 1.60;        // prix au macaron en mode événement-pyramide
// Prix unitaire du macaron en événement : 1,60€ si pyramide présente, sinon tarif événement standard.
