/* ============================================================
   PARAMÈTRES DE GESTION (réglables, persistés en localStorage)
   - Taux de charges sociales : marchandise (produit fini) vs prestation de service
   - Coût emballages/consommables par coffret selon la taille
   ============================================================ */
const EXPORT_REMINDER_DAYS_DEFAULT = 3;   // fréquence par défaut du rappel d'export (jours)
const SETTINGS_DEFAULTS = {
  socialGoods: 12.3,     // % charges sociales sur vente de marchandise (produit fini)
  socialService: 25.6,   // % charges sociales sur prestation de service
  packaging: { 6:1.26, 8:2.18, 16:1.90, 25:2.32 }, // € emballage/consommable par coffret (tarifs réels reçus le 28/11/2025)
  packagingDate: '2025-11-28', // date de réception de référence de ces tarifs (mise à jour à chaque nouvelle réception)
  // Main-d'œuvre (optionnelle) : prise en compte dans le coût de revient si activée.
  laborEnabled: false,   // active/désactive l'ajout du coût de main-d'œuvre
  laborRate: 12.0,       // coût horaire main-d'œuvre (€/h) chargé
  // Source du TEMPS de main-d'œuvre pour le coût de revient :
  //  'manuel' = temps saisi sur chaque recette (minParBatch) ;
  //  'mesure' = temps de production LISSÉ par macaron, mesuré à l'atelier (brique 1, 90 j).
  // En mode 'mesure', si les données mesurées sont insuffisantes, on retombe sur 'manuel'.
  laborSource: 'manuel',
  // Livraison : consommation moyenne du véhicule (L/100 km), pour chiffrer le carburant.
  // Le coût du temps de livraison réutilise laborRate (€/h).
  vehicleConso: 6.5,     // litres aux 100 km
  // PRIX DE VENTE PAR FORMAT (dégressif) — € par macaron selon la taille du coffret.
  // Sert à estimer un prix moyen pondéré et à détecter les incohérences de CA.
  // Le CA réel reste toujours le CA ENCAISSÉ ; cette grille n'établit pas le CA.
  prixParFormat: { 6:2.00, 8:2.00, 16:1.75, 25:1.68 },
  // Prix unitaire de repli (si aucune vente pour pondérer) — recalculé depuis la grille.
  prixVenteUnitaire: 2.00,
  // Tarif PRO au macaron STANDARD (vrac en boîte réutilisable, non facturée). Évolutif.
  prixMacaronProStd: 1.40,
  // Tarif PRO au macaron GRAND FORMAT. Évolutif (le tarif particulier reste à 6,00 €).
  prixGrandFormatPro: 3.20,
  // Types d'emballage pour le comptage avant/après marché (delta) :
  // {nom, cout unitaire €, capacite = nb de macarons par boîte (sert à reconstituer le CA par format)}
  packTypes: [
    {nom:'Boîte 6', cout:0.50, capacite:6},
    {nom:'Boîte 8', cout:0.60, capacite:8},
    {nom:'Boîte 16', cout:1.00, capacite:16},
    {nom:'Boîte 25', cout:1.50, capacite:25}
  ]
};
function getSettings(){
  try{ const s=JSON.parse(localStorage.getItem('sm_settings')||'{}');
    return {
      socialGoods: s.socialGoods!=null?+s.socialGoods:SETTINGS_DEFAULTS.socialGoods,
      socialService: s.socialService!=null?+s.socialService:SETTINGS_DEFAULTS.socialService,
      laborEnabled: s.laborEnabled===true,
      laborRate: s.laborRate!=null?+s.laborRate:SETTINGS_DEFAULTS.laborRate,
      vehicleConso: s.vehicleConso!=null?+s.vehicleConso:SETTINGS_DEFAULTS.vehicleConso,
      prixParFormat: Object.assign({}, SETTINGS_DEFAULTS.prixParFormat, s.prixParFormat||{}),
      prixVenteUnitaire: s.prixVenteUnitaire!=null?+s.prixVenteUnitaire:SETTINGS_DEFAULTS.prixVenteUnitaire,
      prixMacaronProStd: s.prixMacaronProStd!=null?+s.prixMacaronProStd:SETTINGS_DEFAULTS.prixMacaronProStd,
      prixGrandFormatPro: s.prixGrandFormatPro!=null?+s.prixGrandFormatPro:SETTINGS_DEFAULTS.prixGrandFormatPro,
      packaging: Object.assign({}, SETTINGS_DEFAULTS.packaging, s.packaging||{}),
      packagingDate: s.packagingDate || SETTINGS_DEFAULTS.packagingDate,
      packTypes: Array.isArray(s.packTypes) ? s.packTypes : JSON.parse(JSON.stringify(SETTINGS_DEFAULTS.packTypes)),
      consommables: Array.isArray(s.consommables) ? s.consommables : [],
      addressBook: Array.isArray(s.addressBook) ? s.addressBook : [],
      prodCustomTasks: Array.isArray(s.prodCustomTasks) ? s.prodCustomTasks : [],
      exportReminderDays: (parseInt(s.exportReminderDays,10)>0)?parseInt(s.exportReminderDays,10):EXPORT_REMINDER_DAYS_DEFAULT
    };
  }catch(e){ return JSON.parse(JSON.stringify(SETTINGS_DEFAULTS)); }
}
function saveSettings(s){ localStorage.setItem('sm_settings', JSON.stringify(s)); }

// Migration unique : inscrit les tarifs d'emballage reçus le 28/11/2025 dans les réglages

// enregistrés (qui priment sinon sur les nouveaux défauts). Ne s'exécute qu'UNE fois : à ta
// prochaine réception, tu modifieras les prix dans Paramètres et ils ne seront plus écrasés.
function migratePackaging202511(){
  try{
    if(localStorage.getItem('sm_pkg_migr_20251128_v2')==='done') return;
    const raw=JSON.parse(localStorage.getItem('sm_settings')||'{}');
    const cur=raw.packaging||{};
    // N'applique les nouveaux tarifs QUE si l'utilisateur n'a rien personnalisé depuis :
    // soit aucun tarif enregistré, soit exactement les anciens défauts (0.50/0.60/1.00/1.50).
    const estAncienDefaut = (cur[6]==0.50&&cur[8]==0.60&&cur[16]==1.00&&cur[25]==1.50);
    const estVide = !cur || Object.keys(cur).length===0;
    if(estVide || estAncienDefaut){
      raw.packaging = { 6:1.26, 8:2.18, 16:1.90, 25:2.32 };
      raw.packagingDate = '2025-11-28';
      localStorage.setItem('sm_settings', JSON.stringify(raw));
    }
    localStorage.setItem('sm_pkg_migr_20251128_v2','done');
  }catch(e){ console.error('migratePackaging', e); }
}
// Applique les tarifs d'emballage du 28/11/2025, sous contrôle de l'utilisateur (bouton Paramètres).
// Écrit directement dans les réglages (fiable, indépendant de la migration automatique).
function applyPackaging202511(){
  const tarifs={6:1.26, 8:2.18, 16:1.90, 25:2.32};
  try{
    // Écriture DIRECTE dans le localStorage brut (sans passer par getSettings, pour éviter
    // toute réintroduction de valeurs parasites). On remplace entièrement la clé packaging.
    const raw=JSON.parse(localStorage.getItem('sm_settings')||'{}');
    raw.packaging = Object.assign({}, tarifs);   // remplace tout : 6/8/16/25 = tarifs réels
    raw.packagingDate = '2025-11-28';
    localStorage.setItem('sm_settings', JSON.stringify(raw));
    localStorage.setItem('sm_pkg_migr_20251128_v2','done');
  }catch(e){ console.error('applyPackaging202511', e); toast('Erreur d\'enregistrement'); return; }
  // met à jour les champs visibles si le formulaire est ouvert
  Object.keys(tarifs).forEach(t=>{ const el=document.getElementById('set_pk_'+t); if(el) el.value=tarifs[t]; });
  toast('Tarifs emballage du 28/11/2025 appliqués ✓');
  if(typeof settingsForm==='function') settingsForm();   // rouvre le formulaire avec les valeurs à jour + diagnostic
}
// Coût emballage d'un coffret selon sa taille (commandes) — tarif paramétré (repli).
function packagingCost(taille){ const s=getSettings(); const base=(s.packaging[taille]!=null?s.packaging[taille]:0); return money2(base + (typeof consoCoffretSupplement==='function'?consoCoffretSupplement(taille):0)); }

// Coût unitaire RÉEL d'un emballage par capacité, calculé sur les lots d'emballage
// (prix unitaire moyen pondéré par les quantités reçues). Renvoie une Map(capacite → coût).
// Repli silencieux sur le tarif paramétré si aucun lot d'emballage chiffrable.
function realPackagingCostMap(materials, lots){
  const embByCap = new Map();   // capacite -> {coutTotal, qteTotal}
  const embMatCap = new Map();  // materialId -> capacite (pour les matières emballage)
  (materials||[]).forEach(m=>{ if(m.categorie==='emballage' && +m.capacite>0) embMatCap.set(m.id, +m.capacite); });
  (lots||[]).forEach(l=>{
    const cap = embMatCap.get(l.materialId); if(!cap) return;
    const q=+l.qteInitiale||0, pu=lotPU(l); if(q<=0||!(pu>0)) return;
    const cur = embByCap.get(cap) || {coutTotal:0, qteTotal:0};
    cur.coutTotal += pu*q; cur.qteTotal += q; embByCap.set(cap, cur);
  });
  const out = new Map();
  for(const [cap, v] of embByCap){ if(v.qteTotal>0) out.set(cap, money2(v.coutTotal/v.qteTotal)); }
  return out;
}
// Résout le coût unitaire d'un emballage selon la hiérarchie : lot reçu (prix réel) > tarif
// paramétré (réglages packaging, par capacité) > prix de référence (prixDefaut de la matière).
// Renvoie {cout, source} pour pouvoir afficher d'où vient le chiffre.
function embCostHierarchie(mat, lots, settings){
  if(!mat) return {cout:0, source:'—'};
  const s=settings||getSettings();
  // 1) lot reçu chiffré ?
  const sien=(lots||[]).filter(l=>+l.materialId===+mat.id && (+l.qteInitiale||0)>0 && lotPU(l)>0);
  if(sien.length){
    let ct=0,qt=0; sien.forEach(l=>{ const q=+l.qteInitiale||0; ct+=lotPU(l)*q; qt+=q; });
    if(qt>0) return {cout:money2(ct/qt), source:'lot reçu'};
  }
  // 2) tarif paramétré (par capacité) — RÉSERVÉ aux vrais coffrets standards (nom « Coffret N »).
  //    Une boîte spécifique (ex : boîte blanche de capacité 16) ne doit PAS hériter du tarif coffret.
  const estCoffretStd = /^coffret\b/i.test((mat.nom||'').trim()) && BOX_SIZES.includes(+mat.capacite);
  if(estCoffretStd && s.packaging && s.packaging[+mat.capacite]!=null){
    return {cout:money2(+s.packaging[+mat.capacite]), source:'tarif paramétré'};
  }
  // 3) prix de référence de la matière (boîtes blanches, formats spécifiques…)
  if(+mat.prixDefaut>0) return {cout:money2(+mat.prixDefaut), source:'prix de référence'};
  return {cout:0, source:'non défini'};
}
// Coût unitaire RÉEL d'un emballage précis (par materialId) : moyenne pondérée de ses lots
// chiffrés ; à défaut, le prix de référence (prixDefaut) de la matière. Sert au choix
// d'emballage "Autre" sur une ligne coffret.
function embMatUnitCost(matId, materials, lots){
  if(matId==null) return 0;
  let coutTotal=0, qteTotal=0;
  (lots||[]).forEach(l=>{
    if(+l.materialId!==+matId) return;
    const q=+l.qteInitiale||0, pu=lotPU(l); if(q<=0||!(pu>0)) return;
    coutTotal+=pu*q; qteTotal+=q;
  });
  if(qteTotal>0) return money2(coutTotal/qteTotal);
  const m=(materials||[]).find(x=>+x.id===+matId);
  return m && +m.prixDefaut>0 ? money2(+m.prixDefaut) : 0;
}
// Identifie LA matière "coffret standard" d'un format (par nom canonique "Coffret N macarons"),
// pour calculer son coût réel sur SES lots uniquement — sans le confondre avec un autre emballage
// de même capacité (ex: une boîte blanche de capacité 16). Repli : 1re matière emballage de cette
// capacité dont le nom commence par "Coffret".
// Rafraîchit le cache des matières (utilisé par les calculs d'emballage synchrones). À appeler
// après TOUTE modification de matière (ajout/suppression/édition) pour éviter une désynchro
// cache↔base (ids réattribués → coûts d'emballage faux, ex : coffret 16 prenant le prix d'un
// ingrédient à 0,01 €).
async function refreshMatsCache(){
  try{ window._allMatsCache = await db.materials.toArray(); }catch(e){ console.error('refreshMatsCache',e); }
}
function standardCoffretMatId(taille, materials){
  const mats = materials||window._allMatsCache||[];
  const cap=+taille;
  const canon = ('coffret '+cap+' macarons');
  let m = mats.find(x=>x.categorie==='emballage' && (x.nom||'').trim().toLowerCase()===canon);
  if(!m) m = mats.find(x=>x.categorie==='emballage' && +x.capacite===cap && /^coffret\b/i.test((x.nom||'').trim()));
  return m ? m.id : null;
}
// Coût emballage d'une ligne coffret selon son choix (embMode), + libellé lisible pour l'affichage.
// Réutilise exactement la logique de computeOrderMargins pour garantir la cohérence.
function coffretEmbInfo(ln, materials, lots, realMap){
  const _mats = materials||window._allMatsCache||[];
  const mode = ln.embMode||'standard';
  if(mode==='reutilisable') return {cout:0, label:'Réutilisable (client rapporte sa boîte)'};
  if(mode==='autre' && ln.embMatId!=null){
    const m=_mats.find(x=>+x.id===+ln.embMatId);
    return {cout:embMatUnitCost(ln.embMatId, _mats, lots||[]), label:'Autre — '+((m&&m.nom)||'emballage choisi')};
  }
  // STANDARD : coût réel du COFFRET de ce format, calculé sur SES propres lots (pas mélangé avec
  // d'autres emballages de même capacité). Repli sur le tarif paramétré si pas de lot chiffré.
  const stdId = standardCoffretMatId(ln.taille, _mats);
  const supp = (typeof consoCoffretSupplement==='function') ? consoCoffretSupplement(ln.taille) : 0;
  let base;
  if(stdId!=null){
    const hasLot = (lots||[]).some(l=>+l.materialId===+stdId && (+l.qteInitiale||0)>0 && lotPU(l)>0);
    if(hasLot) base = money2(embMatUnitCost(stdId, _mats, lots||[]) + supp);
    else base = packagingCost(ln.taille);   // tarif paramétré (inclut déjà le supplément)
  } else {
    base = packagingCost(ln.taille);
  }
  return {cout:money2(base), label:'Standard (selon la taille)'};
}
// Coût emballage d'un format : réel (lots) si dispo, sinon tarif paramétré.
// Dans les deux cas, on ajoute le supplément des consommables 'coffret' (cartes, stickers…).
function packagingCostReal(taille, realMap){
  const supp = (typeof consoCoffretSupplement==='function') ? consoCoffretSupplement(taille) : 0;
  if(realMap && realMap.has(+taille)) return money2(realMap.get(+taille) + supp);
  return packagingCost(taille); // packagingCost inclut déjà le supplément
}
// Trouve la matière EMBALLAGE correspondant à un format de coffret (par capacité).
async function findPackagingMaterial(taille){
  const mats = await db.materials.toArray();
  return mats.find(m=>m.categorie==='emballage' && +m.capacite===+taille) || null;
}
// Crée les emballages standards (un par format de coffret) s'ils n'existent pas encore.
// Idempotent : ne recrée pas un format déjà présent. Le stock se gère ensuite par lots.
// Crée les 2 boîtes blanches comme matières emballage (idempotent : ne recrée pas si déjà présentes).
// Le coût indiqué est un coût de référence ; il sera affiné par les lots d'emballage reçus.
async function createBoitesBlanches(){
  const aCreer=[
    {nom:'Boîte blch 8/10pcs', capacite:10, prixDefaut:0.14},
    {nom:'Boîte blch 10/16pcs', capacite:16, prixDefaut:0.18}
  ];
  try{
    const mats=await db.materials.toArray();
    let nb=0, dejaLa=[];
    for(const b of aCreer){
      const existe=mats.some(m=>m.categorie==='emballage' && (m.nom||'').trim().toLowerCase()===b.nom.toLowerCase());
      if(existe){ dejaLa.push(b.nom); continue; }
      await db.materials.add({nom:b.nom, unite:'unité', categorie:'emballage', capacite:b.capacite, seuil:0, prixDefaut:b.prixDefaut});
      nb++;
    }
    if(nb>0) toast(`${nb} boîte(s) créée(s) ✓${dejaLa.length?' ('+dejaLa.length+' existait déjà)':''}`);
    else toast('Ces boîtes existent déjà — rien à créer');
    if(typeof settingsForm==='function') settingsForm();   // rouvre les paramètres à jour
  }catch(e){ console.error('createBoitesBlanches',e); toast('Erreur lors de la création'); }
}
async function seedEmballages(){
  const mats = await db.materials.toArray();
  const s = getSettings();
  for(const cap of BOX_SIZES){
    const existe = mats.some(m=>m.categorie==='emballage' && +m.capacite===+cap);
    if(existe) continue;
    const prixDef = (s.packaging && s.packaging[cap]!=null) ? s.packaging[cap] : 0;
    await db.materials.add({nom:`Coffret ${cap} macarons`, unite:'unité', categorie:'emballage',
      capacite:+cap, seuil:0, prixDefaut:prixDef});
  }
}
// Comparateur FIFO des lots de matière/emballage.
// RÈGLE : un lot de REPRISE (stock de départ migration, repriseStock:true) est TOUJOURS
// consommé en premier (priorité absolue), avant tout autre lot. Ensuite, ordre normal :
// DLC la plus proche d'abord, puis réception la plus ancienne.
function lotFifoCompare(a, b){
  const ra = a.repriseStock?0:1, rb = b.repriseStock?0:1;
  if(ra!==rb) return ra-rb;                       // les lots de reprise en tête
  return (a.dlc||'9999').localeCompare(b.dlc||'9999')
      || (a.dateReception||'').localeCompare(b.dateReception||'');
}
// Décrémente `nb` emballages du stock (lots FIFO : reprise d'abord, puis DLC la plus proche).
// Retourne {consomme, manque, materialId} ; ne lève pas si stock insuffisant (consomme ce qui existe).
// À appeler dans une transaction incluant db.materialLots.
async function decrementPackagingStock(taille, nb){
  const mat = await findPackagingMaterial(taille);
  if(!mat) return {consomme:0, manque:nb, materialId:null, absent:true};
  const lots = (await db.materialLots.where('materialId').equals(mat.id).toArray())
    .filter(l=>round3(+l.qteRestante)>0)
    .sort(lotFifoCompare);
  let reste = round3(+nb||0); let consomme=0;
  for(const l of lots){
    if(reste<=0) break;
    const dispo = round3(+l.qteRestante);
    const pris = Math.min(dispo, reste);
    if(pris>0){
      await db.materialLots.update(l.id, {qteRestante: subQty(l.qteRestante, pris)});
      reste = round3(reste - pris); consomme = round3(consomme + pris);
    }
  }
  return {consomme, manque: round3(Math.max(0, reste)), materialId: mat.id, absent:false};
}

// Décrémente `nb` unités du stock d'une matière (par materialId), en FIFO sur ses lots.
// Ne lit QUE db.materialLots → utilisable à l'intérieur d'une transaction rw qui inclut
// materialLots (sans avoir à déclarer db.materials). Sert aux boîtes ET aux sacs.
// Le materialId doit être résolu EN AMONT (hors transaction) via db.materials.
async function decrementLotsByMaterial(materialId, nb){
  if(!materialId) return {consomme:0, manque:round3(+nb||0), materialId:null, absent:true};
  const lots = (await db.materialLots.where('materialId').equals(+materialId).toArray())
    .filter(l=>round3(+l.qteRestante)>0)
    .sort(lotFifoCompare);
  let reste = round3(+nb||0); let consomme=0;
  for(const l of lots){
    if(reste<=0) break;
    const dispo = round3(+l.qteRestante);
    const pris = Math.min(dispo, reste);
    if(pris>0){
      await db.materialLots.update(l.id, {qteRestante: subQty(l.qteRestante, pris)});
      reste = round3(reste - pris); consomme = round3(consomme + pris);
    }
  }
  return {consomme, manque: round3(Math.max(0, reste)), materialId:+materialId, absent:false};
}

// Re-crédite `nb` unités sur les lots d'une matière (par materialId), à l'annulation d'une
// commande. Approche simple : on remet la quantité sur le lot le plus récent encore présent
// (ou, à défaut, sur n'importe quel lot du matériau). Ne lit QUE db.materialLots.
async function restockLotsByMaterial(materialId, nb){
  const n = round3(+nb||0);
  if(!materialId || n<=0) return {credite:0};
  const lots = await db.materialLots.where('materialId').equals(+materialId).toArray();
  if(!lots.length) return {credite:0, absent:true};   // plus aucun lot : rien où recréditer
  // lot le plus récent (réception la plus récente, sinon le dernier id)
  lots.sort((a,b)=> (b.dateReception||'').localeCompare(a.dateReception||'') || (+b.id - +a.id));
  const cible = lots[0];
  await db.materialLots.update(cible.id, {qteRestante: addQty(cible.qteRestante, n)});
  return {credite:n, lotId:cible.id};
}

// Applique au STOCK RÉEL le décompte des emballages d'un marché, à partir du comptage delta
// (sortie − retour) des types RATTACHÉS à une matière (packType.materialId). Gère le différentiel :
// `mk.pkgStockApplied` mémorise {materialId: qté_déjà_décomptée}. À chaque appel on n'applique
// QUE l'écart (re-clôture après correction → ajuste ; réouverture → tout restituer via target=0).
// Si target=0 forcé (param annule=true), on restitue tout le stock déjà décompté.
// Retourne le nouvel objet pkgStockApplied à enregistrer sur le marché.
async function applyMarketPackagingStock(mk, opts){
  opts = opts || {};
  const annule = !!opts.annule;
  const settings = getSettings();
  const packTypes = settings.packTypes || [];
  // matériau rattaché par nom de type (le comptage du marché est indexé par nom)
  const matByTypeName = {};
  packTypes.forEach(t=>{ if(t && t.nom && +t.materialId>0) matByTypeName[t.nom] = +t.materialId; });
  // cible voulue par matériau = Σ (sortie − retour) des types rattachés (0 si annulation)
  const target = {};   // materialId -> qté à avoir décomptée au total
  if(!annule){
    (mk.packaging||[]).forEach(p=>{
      const matId = matByTypeName[p.nom]; if(!matId) return;   // type non rattaché → on ignore le stock
      const used = Math.max(0, round3((+p.before||0)-(+p.after||0)));
      target[matId] = round3((target[matId]||0) + used);
    });
  }
  const already = Object.assign({}, mk.pkgStockApplied || {});
  // ensemble de tous les materialId concernés (cible + déjà appliqué)
  const allIds = new Set([...Object.keys(target), ...Object.keys(already)].map(Number));
  const newApplied = {};
  for(const matId of allIds){
    const want = round3(target[matId]||0);
    const had  = round3(already[matId]||0);
    const diff = round3(want - had);   // >0 : décompter en plus ; <0 : re-créditer
    if(diff > 0){
      await decrementLotsByMaterial(matId, diff);
    } else if(diff < 0){
      await restockLotsByMaterial(matId, -diff);
    }
    if(want > 0) newApplied[matId] = want;   // on ne garde que les positifs
  }
  return newApplied;
}


// Macarons grand format (vente à l'unité), double tarif. Le tarif PRO est évolutif
// (réglable dans les paramètres) ; le tarif particulier reste la référence par défaut.
const BIG_FORMATS = ['Chocolat', 'Myrtille framboise', 'Mangue passion', 'Madeleine'];
const BIG_PRICE = { pro: 3.20, particulier: 6.00 };   // défauts/repli
// 1 macaron assemblé = 2 coques + 1 dose de ganache. Les sous-lots COQUES sont comptés
// en coques ; les sous-lots GANACHE en nombre de macarons garnissables.
const COQUES_PAR_MACARON = 2;
// Ratio matière d'une coque grand format vs une coque standard (1 coque GF = 3,5 coques std).
// S'applique UNIQUEMENT aux coques ; les garnitures d'un GF sont propres à chaque recette.
const GF_COQUE_RATIO = 3.5;
// Prix grand format selon le tarif, en tenant compte du réglage pro évolutif.
function bigPrice(tarif){
  if(tarif==='pro'){ const s=getSettings(); return (s.prixGrandFormatPro!=null)?+s.prixGrandFormatPro:BIG_PRICE.pro; }
  return BIG_PRICE.particulier;
}

// --------- Helpers ---------
// Arrondis & opérations argent/stock : voir utils.js (money2, round3, addMoney,
// subMoney, mulMoney, addQty, subQty) — chargé avant app.js.
// ---- MODE DISCRET / CONFIDENTIALITÉ ----
// Masque les chiffres sensibles (CA, montants, volumes de stock) d'un simple clic,
// utile devant un client ou un fournisseur. Persisté dans localStorage (comme sm_autoPay).
function privacyModeEnabled(){ return localStorage.getItem('sm_privacyMode')==='1'; }
function setPrivacyMode(on){ localStorage.setItem('sm_privacyMode', on?'1':'0'); }
function togglePrivacyMode(){ setPrivacyMode(!privacyModeEnabled()); render(); }

// Suspension ponctuelle du masquage : la SAISIE et le DÉTAIL d'une commande restent
// toujours en clair (on a besoin de voir les prix face au client), même en mode discret.
// _privacySuspend>0 ⇒ euro()/qtyP() n'appliquent pas le masquage.
let _privacySuspend = 0;
function privacyMasked(){ return privacyModeEnabled() && _privacySuspend<=0; }
// Exécute fn() avec le masquage suspendu (utilisé pour le rendu HTML synchrone d'une modale).
function withClearMoney(fn){ _privacySuspend++; try{ return fn(); } finally{ _privacySuspend--; } }

// euro() est privacy-aware : en mode discret, tous les montants deviennent « ••• € »,
// SAUF pendant une suspension (saisie/détail de commande).
// Comme tous les écrans passent par euro(), un seul interrupteur masque l'argent partout.
const euro = n => privacyMasked() ? '••• €'
  : (money2(n)).toLocaleString('fr-FR', {minimumFractionDigits:2, maximumFractionDigits:2}) + ' €';
// Quantité : arrondit proprement (max 3 décimales) et supprime les zéros parasites
const qty = n => { const v = round3(n); return v.toLocaleString('fr-FR', {maximumFractionDigits:3}); };
// AFFICHAGE UNIFORME EN GRAMMES — sans modifier les données stockées.
// Les denrées sont stockées en kg OU en g selon l'historique. Pour un affichage cohérent,
// on convertit toujours vers l'unité de SAISIE lisible : une denrée en kg est montrée en g (×1000).
// Renvoie { n: quantité convertie, u: unité d'affichage }. Les emballages restent inchangés.
// 'mat' peut être l'objet matière complet, ou son unité (chaîne), ou son id (résolu via matUnitGlobal).
function dispUnit(mat){
  let unite='', cat='';
  if(mat && typeof mat==='object'){ unite=(mat.unite||''); cat=(mat.categorie||''); }
  else if(typeof mat==='string'){ unite=mat; }
  else if(typeof mat==='number'){ // id -> on résout via le cache global des matières
    const m=(window._allMatsCache||[]).find(x=>+x.id===+mat) || {};
    unite=(m.unite||''); cat=(m.categorie||'');
  }
  const u=(unite||'').toLowerCase();
  if(cat!=='emballage' && u==='kg') return {f:1000, u:'g'};
  return {f:1, u:unite||''};
}
// Quantité affichée (texte) pour une matière : applique la conversion kg->g si nécessaire.
function qtyDisp(qteStockee, mat){ const d=dispUnit(mat); return qty(round3((+qteStockee||0)*d.f)); }
// Masque un volume de stock en mode discret (sauf suspension).
const qtyP = n => privacyMasked() ? '•••' : qty(n);
// Floute un NOM (client) en mode discret : le texte reste présent (recherche/tri)
// mais s'affiche flouté. Réutilisable partout où un nom sensible apparaît.
const nameP = (txt)=>{
  const s = esc(txt==null?'':String(txt));
  return privacyMasked() ? `<span class="blur-name">${s}</span>` : s;
};

// ============================================================
//  AIDE KPI : un petit « i » cliquable à côté des indicateurs.
//  Chaque chiffre peut être expliqué simplement, sans jargon comptable.
// ============================================================
const KPI_HELP = {
  'ca_mois':       { t:'CA ce mois', d:"Chiffre d'affaires facturé depuis le 1er du mois en cours : la somme de toutes tes commandes datées de ce mois, marchés inclus. C'est ce que tu as facturé, pas forcément encore encaissé." },
  'ca_total':      { t:'CA total', d:"Chiffre d'affaires facturé depuis le tout début, toutes commandes et marchés confondus. Une vue cumulée de toute ton activité." },
  'ca_annee':      { t:'CA cette année', d:"Chiffre d'affaires facturé depuis le 1er janvier de l'année en cours. Utile pour suivre ta progression annuelle." },
  'ca_encaisse':   { t:'CA encaissé', d:"L'argent réellement reçu (règlements enregistrés), à la date du paiement. Différent du CA facturé : une commande facturée mais pas encore payée n'apparaît pas ici." },
  'ca_facture':    { t:'CA facturé', d:"Le total de tes commandes à leur date, qu'elles soient payées ou non. C'est la référence pour ton plafond de micro-entreprise." },
  'macarons_stock':{ t:'Macarons en stock', d:"Le nombre de macarons finis (assemblés et prêts à vendre) actuellement disponibles, tous parfums confondus." },
  'alertes_stock': { t:'Alertes stock', d:"Le nombre de matières premières passées sous leur seuil de réapprovisionnement. Ce sont celles à racheter bientôt pour ne pas tomber en rupture." },
  'taux_perte':    { t:'Taux de perte', d:"La part de ta production qui a été perdue (casse, ratés) par rapport au total produit. Sous 5 % c'est bon, au-dessus de 10 % ça mérite attention.\n\nCalcul : pièces perdues ÷ pièces produites." },
  'valeur_perdue': { t:'Valeur perdue (casse)', d:"Le coût de revient total de ce que tu as déclaré en perte. Ce montant est réimputé sur le coût de tes macarons vendables, car la casse doit être absorbée par ce qui se vend." },
  'panier_moyen':  { t:'Panier moyen', d:"Le montant moyen d'une commande de ce client : son chiffre d'affaires total ÷ son nombre de commandes. Plus il est élevé, plus le client est précieux." },
  'marge_brute':   { t:'Marge brute', d:"Ce qui reste du chiffre d'affaires après avoir retiré les coûts directs de fabrication (matières + emballages), AVANT les charges sociales. C'est ta marge « atelier »." },
  'marge_nette':   { t:'Marge nette', d:"Ce qui reste vraiment après avoir retiré les coûts de fabrication ET les charges sociales (cotisations URSSAF). C'est le plus proche de ton bénéfice réel." },
  'cout_dons':     { t:'Coût des dons', d:"Ce que t'ont coûté les macarons offerts (dégustations, promotions, gestes commerciaux), valorisés à leur coût de revient complet (matières + temps). La « marge après dons » te montre ta marge nette une fois ce coût déduit : utile pour juger si ta générosité reste un bon investissement commercial." },
  'marge_liv':     { t:'Marge après livraison', d:"Ta marge nette une fois déduits aussi les frais de livraison (carburant + temps de trajet). Montre si une livraison « mange » ta marge." },
  'charges_soc':   { t:'Charges sociales', d:"Les cotisations URSSAF dues sur ton chiffre d'affaires. Le taux dépend de la nature : vente de marchandises ou prestation de service (taux différent)." },
  'macarons_vendus':{ t:'Macarons vendus', d:"Le nombre total de macarons écoulés sur la période (commandes + marchés)." },
  'ca_moyen_marche':{ t:'CA moyen / marché', d:"Le chiffre d'affaires moyen que te rapporte un marché : total des ventes sur marchés ÷ nombre de marchés réalisés." },
  'pertes_casse':  { t:'Pertes / casse', d:"La valeur totale de la casse déclarée sur la période, déduite de ton résultat." },
  'cout_revient_rec':{ t:'Coût de revient (par pièce)', d:"Le coût de fabrication d'UN macaron nu : matières premières + consommables directs + main-d'œuvre (si activée), réparti sur les pièces réellement vendables (les pertes renchérissent le coût).\n\nImportant : ce montant n'inclut PAS l'emballage du coffret. L'emballage dépend du format de boîte (6, 8, 16, 25), pas du parfum — il est donc ajouté séparément quand tu composes un coffret, et bien déduit de ta marge à ce moment-là." },
  'taux_marge_rec':{ t:'Taux de marge', d:"La part du prix de vente qui te reste en marge, une fois le coût de revient retiré.\n\nCalcul : marge ÷ prix de vente moyen. Par exemple, un macaron vendu 1,67 € qui coûte 0,11 € à fabriquer laisse 1,56 € de marge, soit 93 %. Plus le pourcentage est élevé, plus le parfum est rentable.\n\nÀ noter : c'est le taux sur le macaron nu ; l'emballage du coffret se déduit au niveau de la commande." },
};
// Génère un petit « i » cliquable qui ouvre l'explication du KPI.
function kpiI(key){
  if(!KPI_HELP[key]) return '';
  return `<button type="button" class="kpi-i" onclick="event.stopPropagation();showKpiHelp('${key}')" title="En savoir plus" aria-label="Explication">i</button>`;
}
function showKpiHelp(key){
  const h = KPI_HELP[key]; if(!h) return;
  openModal(`<h3>${esc(h.t)}</h3>
    <p style="color:#5a4a44;line-height:1.6;white-space:pre-line;margin:8px 0 4px">${esc(h.d)}</p>
    <div class="modal-actions"><button class="btn" onclick="closeModal()">Compris</button></div>`);
}

// today() : voir utils.js
// Calcule la DLC selon l'emplacement, à partir d'un horodatage (calcul SIMPLE, sans historique).
// Règle de base : frigo = +7 jours ; congélateur = +4 mois.
function computeDlc(emplacement, baseIso){
  const d = baseIso ? new Date(baseIso) : new Date();
  if(isFreezer(emplacement)){ d.setMonth(d.getMonth()+4); }
  else { d.setDate(d.getDate()+7); } // frigo (et défaut prudent)
  return d.toISOString().slice(0,10);
}
// ---- EMPLACEMENTS DE STOCKAGE ----
// 1 frigo + 3 congélateurs, chacun identifié par une LETTRE qui s'ajoute au n° de lot
// et apparaît sur l'étiquette pour localiser physiquement la production.
const EMPLACEMENTS = [
  {key:'frigo',   lettre:'F', nom:'Frigo',                type:'frigo',      icon:'🧊'},
  {key:'bahut',   lettre:'B', nom:'Congélateur bahut',    type:'congelateur',icon:'❄️'},
  {key:'colonne', lettre:'C', nom:'Congélateur colonne',  type:'congelateur',icon:'❄️'},
  {key:'petit',   lettre:'A', nom:'Petit congélateur',    type:'congelateur',icon:'❄️'}
];
const EMP_BY_KEY = Object.fromEntries(EMPLACEMENTS.map(e=>[e.key,e]));
const EMP_BY_LETTRE = Object.fromEntries(EMPLACEMENTS.map(e=>[e.lettre,e]));
// ---- CONTENANTS ISOTHERMES MARCHÉ ----
// Glacières identifiées par couleur (repère physique stable) + un sac « métro » à part.
// Servent à répartir des BOÎTES ENTIÈRES (jamais de mélange de parfums dans une boîte) de
// façon équilibrée, pour n'ouvrir qu'un contenant à la fois sur le stand (chaîne du froid).
const COOLERS = [
  {key:'vert',   nom:'Glacière verte',   col:'#3f7d52', ico:'🟢'},
  {key:'bleu',   nom:'Glacière bleue',   col:'#3b6ea5', ico:'🔵'},
  {key:'orange', nom:'Glacière orange',  col:'#d98324', ico:'🟠'},
  {key:'violet', nom:'Glacière violette',col:'#7d5ba6', ico:'🟣'},
  {key:'metro',  nom:'Sac métro',        col:'#6a6a6a', ico:'🎒'},
];
const COOLER_BY_KEY = Object.fromEntries(COOLERS.map(c=>[c.key,c]));
// ---- RÉPARTITION MARCHÉ : boîtes entières ventilées en glacières (assortiment équilibré) ----
// boxesToLoad : [{parfum, lot, prodId, nbMacarons, boiteNom}] — chaque entrée = UNE boîte (1 parfum).
// coolerKeys : liste des contenants utilisés (ex ['vert','bleu','orange']).
// Principe : pour chaque parfum, on répartit ses boîtes en commençant par la glacière la moins
// remplie → chaque glacière reçoit un assortiment équilibré, sans jamais mélanger 2 parfums.
function repartitionMarche(boxesToLoad, coolerKeys){
  const cools = (coolerKeys||[]).filter(k=>COOLER_BY_KEY[k]);
  if(!cools.length) return {parGlaciere:{}, nbBoites:0, coolers:[]};
  const parGlaciere = {}; cools.forEach(k=>parGlaciere[k]={boites:[], nbBoites:0, nbMacarons:0, parfums:{}});
  const parParfum = {};
  (boxesToLoad||[]).forEach(b=>{ (parParfum[b.parfum] ||= []).push(b); });
  Object.keys(parParfum).sort().forEach(parfum=>{
    parParfum[parfum].forEach(boite=>{
      let cible = cools[0];
      for(const k of cools){ if(parGlaciere[k].nbBoites < parGlaciere[cible].nbBoites) cible=k; }
      const g=parGlaciere[cible];
      g.boites.push(boite); g.nbBoites++; g.nbMacarons+=(+boite.nbMacarons||0);
      g.parfums[parfum]=(g.parfums[parfum]||0)+1;
    });
  });
  return {parGlaciere, nbBoites:(boxesToLoad||[]).length, coolers:cools};
}
// Un emplacement est-il un congélateur ? (B, C, A) — sinon frigo (F).
function isFreezer(key){ const e=EMP_BY_KEY[key]; return e ? e.type==='congelateur' : key==='congelateur'; }
function isFrigoKey(key){ const e=EMP_BY_KEY[key]; return e ? e.type==='frigo' : key==='frigo'; }
// Libellé/lettre/icône d'un emplacement (rétro-compat : 'congelateur' générique → bahut par défaut d'affichage).
function empInfo(key){
  if(EMP_BY_KEY[key]) return EMP_BY_KEY[key];
  if(key==='ambiant') return {key:'ambiant', lettre:'T', nom:'Température ambiante', type:'ambiant', icon:'🌡️'};
  if(key==='congelateur') return {key:'congelateur', lettre:'B', nom:'Congélateur', type:'congelateur', icon:'❄️'};
  if(key==='frigo') return EMP_BY_KEY.frigo;
  return {key:key||'', lettre:'?', nom:'—', type:'', icon:''};
}
function empLettre(key){ return empInfo(key).lettre; }
function empNom(key){ return empInfo(key).nom; }
function empIcon(key){ return empInfo(key).icon; }
// Tag HTML coloré d'un emplacement.
// Sur iPad/desktop : icône + nom complet + lettre (ex. « 🌡️ Température ambiante · T »).
// Sur iPhone (CSS @media) : on n'affiche QUE la lettre centrée, en gardant la couleur.
function empTagHtml(key){
  const e=empInfo(key);
  if(!e.key) return '<span class="tag warn">non renseigné</span>';
  const bg = e.type==='frigo' ? '#6aa3a0' : '#3b6ea5';
  return `<span class="tag emp-tag" style="background:${bg};color:#fff" title="${esc(e.nom)}">`
    + `<span class="emp-full">${e.icon} ${esc(e.nom)} · ${e.lettre}</span>`
    + `<span class="emp-letter">${e.lettre}</span></span>`;
}
// Applique/relève la lettre d'emplacement au numéro de lot : « L-…-EMR » + « -A ».
// On retire d'abord un éventuel suffixe -X existant, puis on ajoute la nouvelle lettre.
const EMP_LETTERS = EMPLACEMENTS.map(e=>e.lettre).join(''); // "FBCA"
function lotBaseSansSuffixe(lot){
  if(!lot) return '';
  return String(lot).replace(new RegExp('-[' + EMP_LETTERS + ']$'), '');
}
function lotAvecEmplacement(lot, key){
  const base = lotBaseSansSuffixe(lot);
  const l = empLettre(key);
  return (l && l!=='?') ? `${base}-${l}` : base;
}
// Génère un code aléatoire pour le n° de lot SANS les lettres ambiguës I, L, O
// (confusion avec 1 / 1 / 0). Alphabet : A–Z sauf I/L/O + chiffres 2–9 (0 et 1 exclus aussi).
const LOT_ALPHABET = 'ABCDEFGHJKMNPQRSTUVWXYZ23456789'; // pas de I,L,O ni 0,1
function genLotCode(n){
  n = n||3;
  let s='';
  for(let i=0;i<n;i++) s += LOT_ALPHABET[Math.floor(Math.random()*LOT_ALPHABET.length)];
  return s;
}
// Table des CODES PARFUM pour les numéros de lot (définis par Benjamin).
// En lisant un lot, le code dit immédiatement de quel produit il s'agit.
const FLAVOR_CODES = {
  'Citron crémeux':'CIT', 'Chocolat au lait':'CHL', 'Chocolat noir':'CHN',
  'Framboise':'FRA', 'Vanille':'VAN', 'Pistache':'PIS', 'Coco Rafaello':'RAF',
  'Cannelle noisette':'CAN', 'Caramel beurre salé':'CAR', 'Chocolat passion':'CHP',
  'Nocciolata':'NOC', 'Coco citron vert':'CCV', 'Praliné noisettes':'PRA',
  'Popcorn':'POP', 'Café':'CAF'
};
// Dérive le code parfum à partir d'un nom de recette/produit. Cherche le parfum dont
// le nom est contenu dans le nom de la recette (ex. « Macaron Caramel beurre salé » → CAR).
// Repli : 3 premières lettres alphabétiques si aucun parfum connu n'est reconnu.
function flavorCode(nom){
  const n = normTxt(nom||'');
  // On teste du plus spécifique au plus court pour éviter que 'Chocolat' attrape 'Chocolat noir'.
  const noms = Object.keys(FLAVOR_CODES).sort((a,b)=>normTxt(b).length-normTxt(a).length);
  for(const f of noms){ if(n.includes(normTxt(f))) return FLAVOR_CODES[f]; }
  const lettres = (nom||'').toUpperCase().replace(/[^A-Z]/g,'').replace(/[ILO]/g,'');
  return lettres.slice(0,3) || 'XXX';
}
// Date JJMMAA (jour-mois-année courts) pour le numéro de lot.
function lotDateJJMMAA(d){
  const dt = d ? new Date(d) : new Date();
  const jj = String(dt.getDate()).padStart(2,'0');
  const mm = String(dt.getMonth()+1).padStart(2,'0');
  const aa = String(dt.getFullYear()).slice(-2);
  return jj+mm+aa;
}
// Construit le numéro de lot : JJMMAA + CODE (+ numéro si doublon du jour).
// Le 1er lot du jour pour ce parfum n'a pas de numéro ; les suivants : 2, 3, …
// existants = liste des lotBase déjà utilisés ce jour pour CE parfum (pour calculer le rang).
function buildLotBase(nomProduit, dateStr, existantsMemeJourMemeParfum){
  const code = flavorCode(nomProduit);
  const datePart = lotDateJJMMAA(dateStr);
  const racine = datePart + code;           // ex : 180824CAR
  const dejaCount = (existantsMemeJourMemeParfum||[]).length;
  if(dejaCount<=0) return racine;           // 1er lot : sans numéro
  return racine + (dejaCount+1);            // 2e lot → CAR2, 3e → CAR3, …
}
// Nettoie un n° de lot saisi : met en majuscules et retire les lettres ambiguës I, L, O.
// Renvoie {lot, changed} pour pouvoir prévenir l'utilisateur si une correction a eu lieu.
function sanitizeLot(lot){
  const up = String(lot||'').toUpperCase();
  const cleaned = up.replace(/[ILO]/g, '');
  return {lot:cleaned, changed: cleaned!==up};
}
const FRIGO_DAYS = 7;        // durée de vie totale au frigo (jours)
const CONGELO_MONTHS = 4;    // durée de vie au congélateur (mois)
const MS_DAY = 86400000;
// ÉTATS DE MATURATION d'un lot (champ production.maturation).
// La maturation (repos au froid positif F pour développer les arômes) peut se faire AVANT
// congélation (préférence de Benjamin) ou APRÈS décongélation, ou ne pas être requise.
//  'fait'      : déjà maturé (typiquement maturé avant congélation) → prêt dès décongélation.
//  'apres'     : à maturer APRÈS décongélation → devra passer par F avant d'être livrable.
//  'nonrequis' : maturation non nécessaire pour ce lot.
//  null/undefined : non renseigné (on ne présume rien).
const MATURATION_ETATS = {
  fait:      {label:'Déjà maturé', ico:'✅', desc:'Maturé avant congélation — prêt dès décongélation', c:'#3f7d52'},
  apres:     {label:'À maturer après décongélation', ico:'🕒', desc:'Devra passer par le frigo F avant vente', c:'#d98324'},
  nonrequis: {label:'Maturation non requise', ico:'➖', desc:'Pas d\'étape de maturation pour ce lot', c:'#9a8a82'}
};
function prodMaturation(p){ return p && MATURATION_ETATS[p.maturation] ? p.maturation : null; }
// Un lot congelé est-il prêt à être livré dès décongélation (pas de maturation après) ?
function prodMaturationPrete(p){ const m=prodMaturation(p); return m==='fait' || m==='nonrequis'; }
// Calcule la DLC en TENANT COMPTE de l'historique des emplacements.
// Principe sanitaire : le frigo dispose d'un budget total de 7 jours qui se CONSOMME
// à chaque séjour au frigo (avant ET après congélation). La congélation met le compteur
// en pause (le froid négatif ne consomme pas le budget frigo) et ajoute sa propre limite
// de 4 mois tant que le produit reste congelé.
// hist = [{lieu:'frigo'|'congelateur', ts:ISO, ...}] dans l'ordre chronologique.
// refIso = instant "de référence" (le dernier déplacement, ou maintenant) à partir duquel
// on projette le temps restant pour le segment courant.
function computeDlcFromHistory(hist, refIso){
  if(!Array.isArray(hist) || !hist.length) return null;
  const segs = hist.slice().sort((a,b)=>(a.ts||'').localeCompare(b.ts||''));
  const ref = new Date(refIso||new Date().toISOString());
  let frigoConsumedMs = 0;        // temps frigo déjà consommé (segments clos)
  // parcourt les segments fermés (du début jusqu'à l'avant-dernier) pour cumuler le temps frigo écoulé
  for(let i=0;i<segs.length-1;i++){
    if(!isFreezer(segs[i].lieu)){
      const start=new Date(segs[i].ts), end=new Date(segs[i+1].ts);
      const dur=end-start; if(dur>0) frigoConsumedMs+=dur;
    }
  }
  const last=segs[segs.length-1];
  const lastStart=new Date(last.ts);
  if(isFreezer(last.lieu)){
    // DLC = entrée au congélo + 4 mois (le budget frigo restant est gelé jusqu'à la décongélation)
    const d=new Date(lastStart); d.setMonth(d.getMonth()+CONGELO_MONTHS);
    return d.toISOString().slice(0,10);
  }
  // segment courant = frigo : budget restant = 7j - temps frigo déjà consommé (segments précédents)
  // + temps déjà écoulé dans le segment frigo courant (entre lastStart et ref)
  const currentFrigoElapsed = Math.max(0, ref - lastStart);
  const totalFrigoConsumed = frigoConsumedMs + currentFrigoElapsed;
  const resteMs = Math.max(0, FRIGO_DAYS*MS_DAY - totalFrigoConsumed);
  const dlc=new Date(ref.getTime()+resteMs);
  return dlc.toISOString().slice(0,10);
}
// Horodatage lisible "le JJ/MM/AAAA à HHhMM" à partir d'un ISO.
// Heure seule au format 00:00 (ex : 10:02). Renvoie '' si non valide.
// fmtTime / fmtDateTime : voir utils.js
// --------- Statut de production : démarré / terminé ---------
// Plafond de temps autorisé en statut « démarré » avant blocage (4 jours).
const PROD_OPEN_MAX_DAYS = 4;
// Statut effectif d'une prod (rétro-compat : les anciennes prods sans statut
// sont considérées comme « terminée », avec leur DLC déjà figée).
function prodStatut(p){ return p && p.prodStatut ? p.prodStatut : 'termine'; }
// Composant d'une production : 'complet' (vendable), 'coques'/'ganache' (intermédiaires), 'assemble' (vendable).
function prodComposant(p){ return (p && p.composant) ? p.composant : 'complet'; }
// Libellé d'affichage de la garniture : « Crémeux » si sous-type crémeux, sinon « Ganache ».
// (le composant interne reste 'ganache' pour ne pas casser l'assemblage)
function garnLabel(p){ return (p && p.garnitureType==='cremeux') ? 'crémeux' : 'ganache'; }
function garnIcon(p){ return (p && p.garnitureType==='cremeux') ? '🟠' : '🍫'; }
// Une production est "rangée" (donc sortie de la vue Production) si elle a été DÉLIBÉRÉMENT
// déclarée rangée (champ p.rangee), OU si elle est rattachée à une commande prête/livrée
// (ensemble précalculé _prodLiesCmdPrete, rempli dans renderProductions). Aucune déduction
// automatique au-delà : sans déclaration explicite, une production reste visible.
function prodEstRangee(p){
  if(!p) return false;
  if(p.rangee===true) return true;
  // Tout batch stocké au CONGÉLATEUR (A/B/C) est en stockage long terme → sort de la vue Production,
  // même sans le flag « rangee » (ex. batchs rangés avant cette règle). Le frigo (F) ne compte pas.
  if(p.emplacement && isFreezer(p.emplacement)) return true;
  if(window._prodLiesCmdPrete && window._prodLiesCmdPrete.has(+p.id)) return true;
  // Production ÉPUISÉE : terminée et il ne reste plus rien (assemblée, servie, consommée).
  // Plus rien à gérer → sort de la vue, comme une production rangée. On exige le statut
  // « terminée » pour ne jamais masquer une prod encore en cours qui serait à 0 transitoirement.
  if(prodStatut(p)==='termine' && round3(+p.qteRestante||0)<=0) return true;
  return false;
}
// Un lot est-il un PRODUIT FINI vendable ? (exclut les sous-lots coques/ganache non assemblés)
function prodVendable(p){ const c=prodComposant(p); return c==='complet' || c==='assemble'; }
// Heure d'ancrage de la DLC frigo : le moment où la prod est passée « terminée »
// (ou, pour les anciennes prods, l'horodatage de production).
function prodDlcAnchor(p){ return (p && (p.prodTermineTs || (prodStatut(p)==='termine' ? p.prodTimestamp : ''))) || ''; }
// Heures écoulées depuis le démarrage d'une prod « démarrée ».
function prodOpenHours(p){
  const start = p && (p.prodDebutTs || p.prodTimestamp);
  if(!start) return null;
  return (Date.now() - new Date(start).getTime()) / 3600000;
}
// Une prod « démarrée » dépasse-t-elle le plafond des 4 jours ?
function prodOpenOverdue(p){
  if(prodStatut(p)!=='demarre') return false;
  const h = prodOpenHours(p);
  return h!=null && h > PROD_OPEN_MAX_DAYS*24;
}
// esc() : voir utils.js
function val(id){ const el = document.getElementById(id); return el ? (el.value||'').trim() : ''; }
// Lecture NUMÉRIQUE d'un champ, tolérante au séparateur décimal français (virgule).
// Sur iPhone, le pavé peut produire « 243,5 » : `+"243,5"` donne NaN (→ 0 silencieux et stock vidé).
// numVal() remplace la virgule par un point avant conversion. Retourne 0 si vide/illisible.
function numVal(id){ const s=val(id).replace(',', '.'); const n=parseFloat(s); return isFinite(n)?n:0; }
// fmtDate() / daysTo() : voir utils.js

// --------- Graphique linéaire SVG (sans dépendance) ---------
// series : [{label, points:[{x:'2026-01', y:12.5}], color}]  — x = clé triable
function lineChart(series, opt){
  opt = opt || {};
  const W = opt.w || 640, H = opt.h || 240, pad = {l:48,r:16,t:16,b:34};
  const all = series.flatMap(s=>s.points);
  if(!all.length) return '<div class="empty">Pas encore de données.</div>';
  // axe X = union triée des clés
  const xs = [...new Set(all.map(p=>p.x))].sort((a,b)=>String(a).localeCompare(String(b)));
  const xIdx = {}; xs.forEach((x,i)=>xIdx[x]=i);
  const xPos = i => xs.length<=1 ? pad.l+(W-pad.l-pad.r)/2 : pad.l + i*(W-pad.l-pad.r)/(xs.length-1);
  let ymin = Math.min(...all.map(p=>p.y)), ymax = Math.max(...all.map(p=>p.y));
  if(opt.zero) ymin = Math.min(0,ymin);
  if(ymin===ymax){ ymax = ymin+1; ymin = Math.max(0,ymin-1); }
  const pad2 = (ymax-ymin)*0.12; ymax+=pad2; if(ymin>0) ymin=Math.max(0,ymin-pad2);
  const yPos = v => H-pad.b - (v-ymin)/(ymax-ymin)*(H-pad.t-pad.b);
  // grille + labels Y (4 lignes)
  let grid='';
  for(let i=0;i<=4;i++){
    const v = ymin+(ymax-ymin)*i/4, y=yPos(v);
    grid+=`<line x1="${pad.l}" y1="${y}" x2="${W-pad.r}" y2="${y}" stroke="#f0eae0"/>`;
    grid+=`<text x="${pad.l-6}" y="${y+3}" text-anchor="end" font-size="10" fill="#9a8a82">${opt.fmt?opt.fmt(v):Math.round(v*100)/100}</text>`;
  }
  // labels X (max ~6)
  const step = Math.ceil(xs.length/6);
  let xlab='';
  xs.forEach((x,i)=>{ if(i%step===0||i===xs.length-1) xlab+=`<text x="${xPos(i)}" y="${H-pad.b+16}" text-anchor="middle" font-size="10" fill="#9a8a82">${esc(opt.xlabel?opt.xlabel(x):x)}</text>`; });
  // courbes
  let paths='';
  series.forEach(s=>{
    const col = s.color||'#AA7C39';
    const pts = s.points.slice().sort((a,b)=>String(a.x).localeCompare(String(b.x)));
    if(!pts.length) return;
    const d = pts.map((p,i)=>`${i?'L':'M'}${xPos(xIdx[p.x]).toFixed(1)},${yPos(p.y).toFixed(1)}`).join(' ');
    paths+=`<path d="${d}" fill="none" stroke="${col}" stroke-width="2.5" stroke-linejoin="round"/>`;
    pts.forEach(p=>{ paths+=`<circle cx="${xPos(xIdx[p.x]).toFixed(1)}" cy="${yPos(p.y).toFixed(1)}" r="3.2" fill="${col}"/>`; });
  });
  // légende
  let leg='';
  if(series.length>1 || (series[0]&&series[0].label)){
    leg='<div class="flex" style="gap:16px;margin-top:8px;font-size:.78rem">'+series.map(s=>`<span style="display:inline-flex;align-items:center;gap:6px"><span style="width:14px;height:3px;background:${s.color||'#AA7C39'};display:inline-block;border-radius:2px"></span>${esc(s.label||'')}</span>`).join('')+'</div>';
  }
  return `<svg viewBox="0 0 ${W} ${H}" style="width:100%;height:auto;display:block">${grid}${xlab}${paths}</svg>${leg}`;
}
const ymKey = d => (d||'').slice(0,7);
// CA COMPTABLE par mois d'ENCAISSEMENT : on ventile chaque paiement réel sur le mois de sa date.
// Un paiement en 2 fois (acompte mai + solde août) tombe sur mai ET août, chacun son montant.
// Renvoie { parMois:{'AAAA-MM':montant}, enAttente:montant_non_encore_encaissé }.
// Source de vérité = le registre o.paiements[{date,montant}]. Rétro-compat : si pas de registre
// mais commande marquée payée, on utilise datePaiement/montant.
// --- HELPER CANONIQUE des paiements d'une commande -------------------------------------------
// Renvoie TOUJOURS un tableau normalisé [{date, montant, moyen}] :
//  • si la commande a un registre o.paiements → on le normalise (filtre les montants nuls) ;
//  • sinon si elle est marquée « Payé » → un paiement reconstruit (datePaiement sinon date) ;
//  • sinon (en attente) → [].
// Centralise un pattern qui était dupliqué à ~9 endroits (cohérence comptable garantie).
function paiementsDe(o){
  if(!o) return [];
  if(Array.isArray(o.paiements) && o.paiements.length){
    return o.paiements
      .filter(p=>p && (+p.montant))
      .map(p=>({date:(p.date||o.date||''), montant:money2(+p.montant||0), moyen:(p.moyen||o.reglement||'—')}));
  }
  if(o.paiement==='Payé'){
    return [{date:(o.datePaiement||o.date||''), montant:money2(+o.montant||0), moyen:(o.reglement||'—')}];
  }
  return [];
}
function caEncaisseParMois(orders){
  const parMois={}; let enAttente=0;
  (orders||[]).forEach(o=>{
    if(o.histo) return;
    const paiements = paiementsDe(o);
    let encaisse=0;
    paiements.forEach(p=>{
      const m=+p.montant||0; if(!m) return;
      encaisse+=m;
      const k=ymKey(p.date||o.date||'');
      if(k) parMois[k]=(parMois[k]||0)+m;
    });
    // reste à encaisser sur cette commande → en attente (pas compté dans le CA mensuel)
    const reste=(+o.montant||0)-encaisse;
    if(reste>0.01) enAttente+=reste;
  });
  return { parMois, enAttente: money2(enAttente) };
}
const ymLabel = ym => { const [y,m]=ym.split('-'); return new Date(y,+m-1,1).toLocaleDateString('fr-FR',{month:'short',year:'2-digit'}); };


// --------- Toast & Modal ---------
let tt;
function toast(msg){ const t=document.getElementById('toast'); if(!t) return; t.innerHTML=esc(msg); t.classList.remove('with-action'); t.classList.add('show'); clearTimeout(tt); tt=setTimeout(()=>t.classList.remove('show'),2400); }
// ---- ANNULATION RAPIDE (undo) ----
// Le toast affiche un message + un lien « Annuler » discret, au même endroit que les
// notifications habituelles (non invasif). Disparaît seul après quelques secondes.
let _undoFn=null, _undoTimer=null;
function showUndoToast(label, restoreFn, ms){
  _undoFn=restoreFn;
  const t=document.getElementById('toast'); if(!t){ return; }
  t.innerHTML=`<span class="toast-msg">${esc(label)}</span><button type="button" class="toast-undo" onclick="runUndo()">↩ Annuler</button>`;
  t.classList.add('show','with-action');
  clearTimeout(tt); clearTimeout(_undoTimer);
  _undoTimer=setTimeout(()=>{ hideUndo(); }, ms||6000);
}
function hideUndo(){ const t=document.getElementById('toast'); if(t){ t.classList.remove('show','with-action'); } _undoFn=null; clearTimeout(_undoTimer); }
async function runUndo(){
  const fn=_undoFn; _undoFn=null; clearTimeout(_undoTimer);
  const t=document.getElementById('toast'); if(t) t.classList.remove('show','with-action');
  if(typeof fn==='function'){ try{ await fn(); toast('Action annulée ✓'); }catch(e){ toast('Annulation impossible'); } }
}
const overlay=document.getElementById('overlay'), modal=document.getElementById('modal');
function openModal(html){ modal.innerHTML=html; overlay.classList.add('show');
  if(_histReady && !_popping){ try{ history.pushState({kind:'modal'}, '', '#modal'); }catch(e){} } }
// ============================================================
//  AFFICHAGE D'UN DOCUMENT IMPRIMABLE (facture, étiquettes, liste…)
//  dans une COUCHE intégrée à l'app (pas une fenêtre séparée).
//  → toujours un bouton « Fermer » : plus de blocage après impression.
// ============================================================
function openPrintView(htmlDoc, opts){
  opts = opts || {};
  closePrintView(); // sécurité : pas de doublon
  const wrap = document.createElement('div');
  wrap.id = 'printView';
  wrap.innerHTML = `
    <div class="pv-bar">
      <button class="pv-btn pv-close" onclick="closePrintView()">✕ Fermer</button>
      <span class="pv-title">${esc(opts.title||'Document')}</span>
      ${opts.extraButtons||''}
      <button class="pv-btn pv-print" onclick="printPrintView()">🖨 Imprimer</button>
    </div>
    <div class="pv-body"><iframe id="pvFrame" title="Aperçu"></iframe></div>`;
  document.body.appendChild(wrap);
  const frame = document.getElementById('pvFrame');
  const doc = frame.contentWindow.document;
  doc.open(); doc.write(htmlDoc); doc.close();
  // entrée d'historique pour que le bouton « retour » ferme la vue au lieu de quitter l'app
  if(_histReady){ try{ history.pushState({kind:'printview'}, '', '#print'); }catch(e){} }
  document.body.style.overflow='hidden';
}
function printPrintView(){
  const frame = document.getElementById('pvFrame');
  if(!frame){ return; }
  try{ frame.contentWindow.focus(); frame.contentWindow.print(); }
  catch(e){ try{ window.print(); }catch(_){} }
}
function closePrintView(opts){
  const wrap = document.getElementById('printView');
  if(wrap){ wrap.remove(); }
  document.body.style.overflow='';
  opts=opts||{};
  if(_histReady && !_popping && !opts.fromPop && history.state && history.state.kind==='printview'){
    try{ history.back(); }catch(e){}
  }
}
function closeModal(opts){
  overlay.classList.remove('show'); modal.innerHTML='';
  _privacySuspend=0; // fin d'une éventuelle suspension du masquage (saisie/détail commande)
  // sécurité : couper toute caméra de scan encore active
  if(typeof stopScanStream==='function'){ try{ stopScanStream(); }catch(e){} }
  // si fermeture déclenchée par l'utilisateur (pas par un retour navigateur), consommer l'entrée d'historique
  opts=opts||{};
  if(_histReady && !_popping && !opts.fromPop && history.state && history.state.kind==='modal'){
    try{ history.back(); }catch(e){}
  }
}
overlay.addEventListener('click', e => { if(e.target===overlay) closeModal(); });

// --------- Router ---------
let view='dash';
const VIEWS = {
  dash:renderDash, clients:renderClients, commandes:renderCmd, produits:renderProducts, cal:renderCal,
  fournisseurs:renderSuppliers, matieres:renderMaterials, recettes:renderRecipes, achats:renderAchats,
  productions:renderProductions, couts:renderCosts, dlc:renderDlc, picking:renderPicking, mrp:renderMRP,
  tracabilite:renderTrace, etiquettes:renderLabels, stats:renderStats, compta:renderCompta, pilotage:renderPilotage, rentabilite:renderProfit, rentaparfum:renderParfums, stockparfums:renderStockParfums, marches:renderMarkets, analyse:renderAnalyse, previsionnel:renderForecast, evenements:renderEvents, sauvegardes:renderBackups, integrite:renderIntegrity, atelier:renderAtelier, guide:renderGuide, assistant:renderAssistant, pms:renderPMS, migration:renderMigration, revenuhoraire:renderRevenuHoraire, consommables:renderConsommables, boites:renderBoites, equipements:renderEquipements, composants:renderComposants, documents:renderDocuments
};
let _navLast=0;
let _popping=false;        // vrai quand on traite un retour (popstate) pour éviter de re-pousser
let _histReady=false;
function setActiveView(v){
  document.querySelectorAll('.nav button, .tabbar button, .sheet-grid button').forEach(x=>{
    if(x.dataset && x.dataset.v) x.classList.toggle('active', x.dataset.v===v);
  });
  // La mascotte n'est présente que sur l'accueil (dash) ; masquée ailleurs.
  if(typeof mascotSetVisible==='function') mascotSetVisible(v==='dash');
}
function navTo(b){
  if(!b || !b.dataset || !b.dataset.v) return;
  const now=Date.now(); if(now-_navLast<120 && view===b.dataset.v && !document.getElementById('sheetOverlay').classList.contains('show')) return; _navLast=now;
  goView(b.dataset.v);
  closeSheet();
}
// Navigation centralisée : change la vue ET empile une entrée d'historique (bouton Retour iOS).
function goView(v, opts){
  opts=opts||{};
  // Filet de sécurité HACCP : si on quitte l'écran Températures avec des valeurs
  // saisies mais non validées, on prévient (évite la perte silencieuse de relevés).
  if(typeof pmsGuardUnsaved==='function' && view==='pms' && v!=='pms'){
    if(!pmsGuardUnsaved()) return;
  }
  if(typeof hideUndo==='function') hideUndo();
  view=v; setActiveView(view); render();
  if(_histReady && !_popping && !opts.replace){
    try{ history.pushState({view:v, kind:'view'}, '', '#'+v); }catch(e){}
  }
}
// Renvoie true s'il existe une température MODIFIÉE et non encore validée dans l'écran courant.
// On compare la valeur affichée à la valeur déjà enregistrée (data-saved) : un relevé déjà
// validé puis simplement réaffiché ne compte PAS comme « non enregistré ».
function pmsHasUnsavedTemp(){
  if(_pmsTab!=='temp') return false;
  const sels=document.querySelectorAll('select[id^="pmsT_"]');
  for(const s of sels){
    const cur = s.value;
    const saved = s.getAttribute('data-saved')||'';
    // une vraie modification = valeur courante différente de la valeur enregistrée
    if(cur!==saved && cur!=='' && !isNaN(+cur)) return true;
  }
  return false;
}
// Garde-fou : si une température a été MODIFIÉE sans être revalidée, on demande confirmation
// avant de quitter. Message neutre (pas de « perte de données ») : il s'agit seulement d'un
// relevé non encore validé. Robuste si confirm() est indisponible (PWA iOS).
function pmsGuardUnsaved(){
  if(!pmsHasUnsavedTemp()) return true;
  let ok;
  try{
    ok = window.confirm('Un relevé de température a été modifié mais pas encore validé.\n\nTouche « ✓ Valider les relevés » pour l\'enregistrer.\n\nContinuer sans valider cette modification ?');
  }catch(e){ ok = undefined; }
  // Si confirm() n'est pas exploitable (certaines PWA iOS), on ne bloque pas la navigation
  // mais on prévient clairement par un toast.
  if(ok===undefined){
    if(typeof toast==='function') toast('ℹ️ Relevé modifié non validé — pense à « Valider les relevés »');
    return true;
  }
  return ok;
}
function openSheet(){
  const o=document.getElementById('sheetOverlay'); if(o){ o.classList.add('show'); setActiveView(view);
    navAdvEnsureVisible();
    const pb=document.getElementById('sheetPrivacyBtn'); if(pb) pb.textContent = privacyModeEnabled()?'👁️ Afficher les données':'🙈 Mode discret';
    if(_histReady && !_popping){ try{ history.pushState({kind:'sheet'}, '', '#menu'); }catch(e){} } }
}
function closeSheet(){ const o=document.getElementById('sheetOverlay'); if(o) o.classList.remove('show'); }

/* ============================================================
   MENU RADIAL (camembert) — surgit du coin inférieur droit
   ============================================================ */
const RADIAL_ITEMS = [
  { label:'Pointeuse', act:()=>{ if(typeof ttStart==='function') ttStart(); } },
  { label:'Commande',  act:()=>goView('commandes') },
  { label:'Calendrier',act:()=>goView('cal') },
];
let _rmState = { open:false, active:-1, startX:0, startY:0, tracking:false };

// Construit le SVG du camembert (quart de cercle, pivot au coin bas-droit).
function radialBuild(){
  const host=document.getElementById('radialMenu'); if(!host) return;
  const N=RADIAL_ITEMS.length;
  const cx=100, cy=100, rOut=96, rIn=20;      // coin bas-droit = (100,100)
  // secteur balayé : de 180° (gauche) à 270° (haut) — quart haut-gauche, naturel pour le pouce
  const a0=180, a1=270, span=a1-a0;
  const rad=d=>d*Math.PI/180;
  const pt=(r,deg)=>[cx+r*Math.cos(rad(deg)), cy+r*Math.sin(rad(deg))];
  let segs='', labels='';
  for(let i=0;i<N;i++){
    const s=a0+span*(i/N), e=a0+span*((i+1)/N);
    const [x1,y1]=pt(rOut,s), [x2,y2]=pt(rOut,e);
    const [x3,y3]=pt(rIn,e),  [x4,y4]=pt(rIn,s);
    const large = (e-s)>180?1:0;
    const d=`M${x1.toFixed(2)},${y1.toFixed(2)} A${rOut},${rOut} 0 ${large} 1 ${x2.toFixed(2)},${y2.toFixed(2)} `
          +`L${x3.toFixed(2)},${y3.toFixed(2)} A${rIn},${rIn} 0 ${large} 0 ${x4.toFixed(2)},${y4.toFixed(2)} Z`;
    const mid=(s+e)/2, rl=(rOut+rIn)/2;
    segs+=`<path class="rm-seg" data-i="${i}" data-mid="${mid.toFixed(1)}" d="${d}"></path>`;
    const [lx,ly]=pt(rl,mid);
    // rotation du label pour suivre l'arc, en gardant le texte lisible
    let rot=mid-180; if(rot>90)rot-=180; if(rot<-90)rot+=180;
    labels+=`<text class="rm-label" data-i="${i}" x="${lx.toFixed(1)}" y="${ly.toFixed(1)}" transform="rotate(${rot.toFixed(1)} ${lx.toFixed(1)} ${ly.toFixed(1)})">${esc(RADIAL_ITEMS[i].label)}</text>`;
  }
  host.innerHTML=`<svg viewBox="0 0 100 100" aria-label="Menu rapide">
    <path class="rm-disc" d="M100,4 A96,96 0 0 1 100,100 L100,100 Z M4,100 A96,96 0 0 0 100,100"></path>
    <path class="rm-disc" d="M${cx},${cy-rOut-2} A${rOut+2},${rOut+2} 0 0 1 ${cx-rOut-2},${cy} L${cx},${cy} Z"></path>
    ${segs}${labels}</svg>`;
  host.classList.add('peek');
}

function radialSetActive(i){
  if(_rmState.active===i) return;
  _rmState.active=i;
  document.querySelectorAll('#radialMenu .rm-seg').forEach(el=>{
    const on = (+el.dataset.i===i);
    el.classList.toggle('active', on);
    if(on){
      // la part se DÉTACHE nettement vers l'extérieur (direction de son angle médian) et grossit
      const mid=+el.dataset.mid||225;
      const rad=mid*Math.PI/180;
      const dx=Math.cos(rad)*16, dy=Math.sin(rad)*16;   // détachement marqué hors du camembert
      el.style.transform=`translate(${dx.toFixed(2)}px,${dy.toFixed(2)}px) scale(1.14)`;
      el.style.transformOrigin='100% 100%';
      el.parentNode.appendChild(el);                  // passe au-dessus des autres
    } else {
      el.style.transform='';
    }
  });
  document.querySelectorAll('#radialMenu .rm-label').forEach(el=>el.classList.toggle('active', +el.dataset.i===i));
  if(i>=0 && navigator.vibrate) navigator.vibrate(8);
}

function radialOpen(){
  const host=document.getElementById('radialMenu'); if(!host) return;
  _rmState.open=true; host.classList.remove('peek'); host.classList.add('open');
  let sc=document.getElementById('radialScrim');
  if(!sc){ sc=document.createElement('div'); sc.id='radialScrim'; document.body.appendChild(sc); }
  sc.classList.add('show');
}
function radialClose(openIndex){
  const host=document.getElementById('radialMenu');
  const sc=document.getElementById('radialScrim');
  if(sc) sc.classList.remove('show');
  // si une part est validée : on la PROJETTE vers la gauche (effet "lancer la part"), puis on ouvre
  if(openIndex!=null && openIndex>=0 && RADIAL_ITEMS[openIndex]){
    const seg=document.querySelector(`#radialMenu .rm-seg[data-i="${openIndex}"]`);
    const lbl=document.querySelector(`#radialMenu .rm-label[data-i="${openIndex}"]`);
    if(seg){
      seg.style.transition='transform .3s cubic-bezier(.3,0,.4,1), opacity .3s ease';
      seg.style.transform='translate(-180px,-90px) scale(1.5)'; seg.style.opacity='0';
    }
    if(lbl){ lbl.style.transition='opacity .18s ease'; lbl.style.opacity='0'; }
    if(host){ setTimeout(()=>{ host.classList.remove('open'); host.classList.add('peek'); }, 140); }
    _rmState.open=false; _rmState.active=-1; _rmState.tracking=false;
    setTimeout(()=>{
      RADIAL_ITEMS[openIndex].act();
      // réinitialise les styles inline des parts pour le prochain affichage
      document.querySelectorAll('#radialMenu .rm-seg,#radialMenu .rm-label').forEach(el=>{ el.style.transform=''; el.style.opacity=''; el.style.transition=''; el.classList.remove('active'); });
    }, 230);
    return;
  }
  // annulation simple : on referme sans rien ouvrir
  if(host){ host.classList.remove('open'); host.classList.add('peek'); }
  _rmState.open=false; _rmState.active=-1; _rmState.tracking=false;
  document.querySelectorAll('#radialMenu .rm-seg,#radialMenu .rm-label').forEach(el=>{ el.style.transform=''; el.style.opacity=''; el.classList.remove('active'); });
}

// Détermine quelle part est sous le point (x,y) à l'écran.
function radialHitTest(x,y){
  const els=document.elementsFromPoint(x,y);
  for(const el of els){ if(el.classList&&el.classList.contains('rm-seg')) return +el.dataset.i; }
  return -1;
}

function radialInit(){
  radialBuild();
  const W=window.innerWidth, H=window.innerHeight;
  // zone d'amorce d'OUVERTURE : coin inférieur droit
  const inCorner=(x,y)=> x > W*0.72 && y > H*0.74;
  // état du geste de FERMETURE (balayage vers le coin pour revenir à l'accueil)
  let _cl={tracking:false, x0:0, y0:0};
  const mainEl=()=>document.getElementById('main');
  window.addEventListener('touchstart', e=>{
    const t=e.touches[0]; if(!t) return;
    if(!_rmState.open && inCorner(t.clientX,t.clientY)){
      _rmState.tracking=true; _rmState.startX=t.clientX; _rmState.startY=t.clientY;
    }
    // amorce fermeture : pouce posé HORS du coin, et on n'est pas déjà sur l'accueil
    else if(!_rmState.open && view!=='dash' && !inCorner(t.clientX,t.clientY)){
      _cl.tracking=true; _cl.x0=t.clientX; _cl.y0=t.clientY;
      _cl.lastX=t.clientX; _cl.lastY=t.clientY; _cl.armed=false;
    }
  }, {passive:true});
  window.addEventListener('touchmove', e=>{
    const t=e.touches[0]; if(!t) return;
    // --- geste d'ouverture du camembert ---
    if(_rmState.tracking){
      const dx=t.clientX-_rmState.startX, dy=t.clientY-_rmState.startY;
      if(!_rmState.open && (dx<-26 || dy<-26)){ radialOpen(); }
      if(_rmState.open){ e.preventDefault(); radialSetActive(radialHitTest(t.clientX,t.clientY)); }
      return;
    }
    // --- geste de fermeture vers le coin (retour accueil) ---
    if(_cl.tracking){
      const dx=t.clientX-_cl.x0, dy=t.clientY-_cl.y0;
      // CONTINUITÉ : le pouce doit progresser sans repartir en arrière.
      // Si à un instant il recule (vers le haut ou la gauche) par rapport au point le plus avancé,
      // on ABANDONNE le geste (c'était un scroll ou une hésitation, pas un vrai retour).
      const lastX=_cl.lastX!=null?_cl.lastX:t.clientX, lastY=_cl.lastY!=null?_cl.lastY:t.clientY;
      const goingBack = (t.clientX < lastX-4) || (t.clientY < lastY-4);
      _cl.lastX=t.clientX; _cl.lastY=t.clientY;
      if(goingBack){
        // direction inversée → on annule proprement et on laisse l'écran revenir
        if(_cl.armed){ const m=mainEl(); if(m){ m.style.transition='transform .18s ease,opacity .18s ease'; m.style.transform=''; m.style.opacity=''; m.style.borderRadius=''; m.style.boxShadow=''; } }
        _cl.tracking=false; _cl.armed=false; return;
      }
      // vrai mouvement diagonal vers le coin bas-droite (évite de capturer un scroll vertical) :
      // déplacement vers la droite ET vers le bas, équilibré (ni quasi-horizontal ni quasi-vertical).
      const diag = dx>16 && dy>16 && dx > dy*0.5 && dy > dx*0.5;
      if(diag || _cl.armed){
        _cl.armed=true;
        e.preventDefault();
        const m=mainEl();
        if(m){
          // La page SUIT LE DOIGT : translation = déplacement réel du pouce (effet "feuille").
          // Légère rotation + réduction progressive ancrées au coin bas-droite pour l'effet page-turn.
          const prog=Math.min(1, Math.hypot(dx,dy)/Math.hypot(W,H)); // 0→1 sur la diagonale écran
          const rot = prog*8;                 // bascule légère (deg)
          const sc  = 1 - 0.18*prog;          // réduction douce
          m.style.transition='none';
          m.style.transformOrigin='100% 100%';
          m.style.transform=`translate(${dx}px,${dy}px) rotate(${rot.toFixed(2)}deg) scale(${sc.toFixed(3)})`;
          m.style.opacity=String(1-0.15*prog);
          m.style.borderRadius=(prog*18).toFixed(0)+'px';
          m.style.boxShadow=prog>0.02?`-12px -12px 30px rgba(0,0,0,${(0.18*prog).toFixed(2)})`:'';
        }
      }
    }
  }, {passive:false});
  const finishClose=(commit)=>{
    const m=mainEl();
    if(!m){ _cl.tracking=false; return; }
    if(commit){
      // 1) fige l'état visuel actuel de la page dans un CALQUE qui se superpose,
      //    avec la transformation en cours (translation/rotation/échelle déjà appliquées).
      const rect=m.getBoundingClientRect();
      const ghost=m.cloneNode(true);
      ghost.id='radialGhost';
      ghost.style.cssText=`position:fixed;left:0;top:0;width:100%;z-index:58;margin:0;
        pointer-events:none;transform:${m.style.transform||''};opacity:${m.style.opacity||1};
        transform-origin:100% 100%;border-radius:${m.style.borderRadius||0};box-shadow:${m.style.boxShadow||'none'};
        background:var(--creme,#F5F0E8)`;
      document.body.appendChild(ghost);
      // 2) on remet la vraie page à zéro et on rend l'ACCUEIL DESSOUS, immédiatement.
      m.style.transition='none'; m.style.transform=''; m.style.opacity='';
      m.style.borderRadius=''; m.style.boxShadow=''; m.style.transformOrigin='';
      if(view!=='dash') goView('dash');
      // 3) on anime le calque qui glisse et sort, révélant l'accueil déjà présent dessous.
      requestAnimationFrame(()=>{
        ghost.style.transition='transform .28s cubic-bezier(.4,0,.6,1), opacity .28s ease';
        ghost.style.transform='translate(100%,100%) rotate(10deg) scale(.5)';
        ghost.style.opacity='0';
        setTimeout(()=>{ ghost.remove(); }, 320);
      });
    } else {
      // pas validé : la feuille revient se poser en place
      m.style.transition='transform .24s ease, opacity .24s ease';
      m.style.transform=''; m.style.opacity=''; m.style.borderRadius=''; m.style.boxShadow='';
      setTimeout(()=>{ if(m){ m.style.transition=''; m.style.transformOrigin=''; } }, 240);
    }
    _cl.tracking=false;
  };
  const endH=(e)=>{
    if(_rmState.tracking){
      if(_rmState.open){ radialClose(_rmState.active); } else { _rmState.tracking=false; }
      return;
    }
    if(_cl.tracking){
      // validation : geste réellement engagé en diagonale (armed) ET amplitude suffisante
      const ch=e.changedTouches&&e.changedTouches[0];
      const dx=ch?ch.clientX-_cl.x0:0, dy=ch?ch.clientY-_cl.y0:0;
      const ok = _cl.armed && dx>60 && dy>60 && Math.hypot(dx,dy)>120;
      finishClose(ok);
      _cl.armed=false;
    }
  };
  window.addEventListener('touchend', endH);
  window.addEventListener('touchcancel', endH);
}

