// DIAGNOSTIC : décompose le CA total des commandes par catégorie de ligne, pour comprendre
// l'écart entre le CA total (tableau de bord) et le CA ventilé par parfum (rentabilité).
function diagFlavorCAGap(orders, markets, marketMoves){
  // IMPORTANT : ce diagnostic suit EXACTEMENT la même logique que buildFlavorSales (v339+),
  // pour que les chiffres soient cohérents. Le CA est calé sur le montant réel encaissé ;
  // la part macarons va aux parfums, la part prestation reste à part.
  const TYPES_MACARON = ['coffret','evenement','vrac','grand','histo'];
  const lineParfumsOf = ln => (ln.type==='grand' ? (ln.items||[]) : (ln.parfums||[])).filter(p=>+p.qte>0);
  const cat = { total:0, ventileParfum:0, prestation:0, marches:0, marchesNonVentiles:0,
                sansParfum:0, pyramides:0 };
  const nb = { prestation:0, sansParfum:0, marchesNonVentiles:0 };
  let totalCmd=0;
  (orders||[]).forEach(o=>{
    const montant = money2(+o.montant||0);
    totalCmd += montant;
    const lignes = orderToLines(o);
    if(!lignes.length){ cat.sansParfum += montant; nb.sansParfum++; return; }
    // Valeur catalogue macarons vs prestation (même calcul que buildFlavorSales).
    let valMac=0, valPresta=0, totalPiecesMac=0;
    lignes.forEach(ln=>{
      if(ln.type==='prestation'){ valPresta += money2(lineTotalStored(ln)); }
      else if(TYPES_MACARON.includes(ln.type)){
        valMac += money2(lineTotalStored(ln));
        lineParfumsOf(ln).forEach(p=>totalPiecesMac+=+p.qte);
      }
      if(ln.type==='evenement'){ cat.pyramides += (+ln.equip||0)*EQUIP_PRICE; }
    });
    if(totalPiecesMac<=0){ cat.sansParfum += montant; nb.sansParfum++; return; }
    // Répartition du montant réel entre macarons (→ parfums) et prestation (→ à part).
    let caMacaron;
    if(valPresta>0 && valMac>0) caMacaron = money2(montant * valMac/(valMac+valPresta));
    else if(valPresta>0 && valMac<=0) caMacaron = 0;
    else caMacaron = montant;
    cat.ventileParfum += caMacaron;
    const partPresta = money2(montant - caMacaron);
    if(partPresta>0.005){ cat.prestation += partPresta; nb.prestation++; }
  });
  // Marchés clos.
  const movesByMk={}; (marketMoves||[]).forEach(mv=>{ (movesByMk[mv.marketId] ||= []).push(mv); });
  (markets||[]).filter(mk=>mk.statut==='clos').forEach(mk=>{
    const caMk = (typeof marketNetCA==='function') ? marketNetCA(mk) : (+mk.montant||0);
    if(caMk<=0) return;
    const mv = movesByMk[mk.id]||[];
    // Pièces réellement vendues = sorties - retours - dons - pertes (ce qui sert à ventiler).
    let vendu=0;
    mv.forEach(m=>{ const q=+m.qte||0; if(m.type==='sortie') vendu+=q; else if(m.type==='retour'||m.type==='don'||m.type==='perte') vendu-=q; });
    cat.marches += caMk;
    if(vendu>0){ /* ventilé via buildFlavorSales */ }
    else { cat.marchesNonVentiles += caMk; nb.marchesNonVentiles++; }
  });
  cat.total = money2(totalCmd + cat.marches);
  cat.totalCmd = money2(totalCmd);
  cat.totalMarches = money2(cat.marches);
  Object.keys(cat).forEach(k=>{ if(typeof cat[k]==='number') cat[k]=money2(cat[k]); });
  cat._nb = nb;
  return cat;
}
// Compte les coffrets vendus par taille (nombre + CA réel encaissé), pour l'indicateur.
function coffretsParTaille(orders){
  const map = {};   // taille -> {nb, ca, pieces}
  (orders||[]).forEach(o=>{
    orderToLines(o).forEach(ln=>{
      if(ln.type!=='coffret') return;
      const t = +ln.taille||0; if(t<=0) return;
      const m = (map[t] ||= {taille:t, nb:0, ca:0, pieces:0});
      m.nb += 1;
      m.pieces += t;
      m.ca = money2(m.ca + money2(lineTotalStored(ln)));
    });
  });
  const list = Object.values(map).sort((a,b)=>b.nb-a.nb);
  const totNb = list.reduce((s,x)=>s+x.nb,0);
  const totCA = money2(list.reduce((s,x)=>s+x.ca,0));
  return { list, totNb, totCA, best: list[0]||null };
}
// Rentabilité des GRANDS FORMATS (gros macarons à l'unité).
// Compte les ventes par produit (type 'grand'), CA réel encaissé, et marge si la recette existe.
function bigFormatStats(orders, recipes, recipeItems, lots){
  const recByNorm={}; (recipes||[]).forEach(r=>{ recByNorm[aiNormalize(r.produitNom)]=r; });
  const map={};   // nom -> {nom, qte, ca, recipe, coutUnit}
  (orders||[]).forEach(o=>{
    orderToLines(o).forEach(ln=>{
      if(ln.type!=='grand') return;
      const items=(ln.items||[]).filter(p=>+p.qte>0);
      const totPieces=items.reduce((s,p)=>s+(+p.qte||0),0);
      if(totPieces<=0) return;
      const caLigne=money2(lineTotalStored(ln));            // CA réel de la ligne
      const caParPiece=totPieces>0?caLigne/totPieces:0;
      items.forEach(p=>{
        const m=(map[p.nom] ||= {nom:p.nom, qte:0, ca:0, recipe:null, coutUnit:null});
        m.qte += +p.qte;
        m.ca = money2(m.ca + caParPiece*(+p.qte));
      });
    });
  });
  // Coût de revient par produit, si une recette grand format correspond.
  Object.values(map).forEach(m=>{
    const r=recByNorm[aiNormalize(m.nom)];
    if(r && r.grandFormat){
      m.recipe=r;
      try{ const cr=coutRevientRecette(r, recipeItems, lots); m.coutUnit=+cr.coutRevientUnit||0; }catch(e){ m.coutUnit=null; }
    }
  });
  const list=Object.values(map).map(m=>{
    const prixMoyen = m.qte>0 ? money2(m.ca/m.qte) : 0;
    const coutTot = (m.coutUnit!=null) ? money2(m.coutUnit*m.qte) : null;
    const marge = (coutTot!=null) ? money2(m.ca-coutTot) : null;
    const tauxMarge = (marge!=null && m.ca>0) ? Math.round(marge/m.ca*1000)/10 : null;
    return {...m, prixMoyen, coutTot, marge, tauxMarge};
  }).sort((a,b)=>b.qte-a.qte);
  const totQte=list.reduce((s,x)=>s+x.qte,0);
  const totCA=money2(list.reduce((s,x)=>s+x.ca,0));
  const totMarge=list.some(x=>x.marge!=null) ? money2(list.reduce((s,x)=>s+(x.marge||0),0)) : null;
  return { list, totQte, totCA, totMarge, best:list[0]||null };
}
async function renderParfums(){
  const [recipes, recipeItems, lots, mats, orders, markets, marketMoves, productions] = await Promise.all([
    db.recipes.toArray(), db.recipeItems.toArray(), db.materialLots.toArray(), db.materials.toArray(),
    db.orders.toArray(), db.markets.toArray(), db.marketMoves.toArray(), db.productions.toArray()
  ]);
  const s = getSettings();
  const data = {recipes, recipeItems, lots, mats, orders, markets, marketMoves, productions, settings:s};

  if(!recipes.length){
    document.getElementById('main').innerHTML=`
      <div class="topbar"><div><h1>Rentabilité parfums</h1><p>Coûts de revient & marges par parfum</p></div></div>
      <div class="panel"><div class="empty">Aucune recette. Créez vos recettes (BOM) — chaque recette correspond à un parfum — puis réceptionnez des lots avec prix pour activer l'analyse.</div></div>`;
    return;
  }

  const A = analyzeFlavorProfitability(data);
  _parfumsA = A;   // mémorisé pour les popups détaillés (marges, prix moyen, stock)
  const hikes = flavorCostHikeAlerts(data, A);
  const recs = flavorRecommendations(A, data);

  // tri
  const rows=[...A.rows];
  const sorters={
    marge:(a,b)=>b.margeBrute-a.margeBrute,
    ca:(a,b)=>b.ca-a.ca,
    pieces:(a,b)=>b.piecesVendues-a.piecesVendues,
    taux:(a,b)=>(b.tauxMarge==null?-1:b.tauxMarge)-(a.tauxMarge==null?-1:a.tauxMarge),
    stock:(a,b)=>b.valStockCout-a.valStockCout,
    nom:(a,b)=>a.nom.localeCompare(b.nom)
  };
  rows.sort(sorters[_parfumSort]||sorters.marge);

  // Pareto 80/20 (sur marge brute, parfums vendus uniquement)
  const sold=A.rows.filter(r=>r.piecesVendues>0 && r.margeBrute>0).sort((a,b)=>b.margeBrute-a.margeBrute);
  const totMargeSold=sold.reduce((s2,r)=>s2+r.margeBrute,0);
  let cum=0; const pareto=[]; let seuil80=null;
  sold.forEach((r,i)=>{ cum+=r.margeBrute; const pct=totMargeSold>0?cum/totMargeSold*100:0; pareto.push({...r, cumPct:pct}); if(seuil80===null && pct>=80) seuil80=i+1; });

  // classements
  const best=A.rows.filter(r=>r.tauxMarge!=null).sort((a,b)=>b.tauxMarge-a.tauxMarge).slice(0,5);
  const worst=A.rows.filter(r=>r.tauxMarge!=null).sort((a,b)=>a.tauxMarge-b.tauxMarge).slice(0,5);

  // KPI
  const avgP = computeAvgSellPrice(data);
  _parfumsAvgP = avgP;
  // Indicateur : rentabilité des grands formats (gros macarons).
  const bf = bigFormatStats(orders, recipes, recipeItems, lots);
  const bigBox = bf.totQte>0 ? `<div class="panel" style="margin-bottom:12px">
    <h2>🍪 Rentabilité grands formats</h2>
    ${bf.best?`<div class="banner" style="background:#f6f1e8;border-color:#8a6d3b;margin:4px 0 10px"><div>🏆 Le plus vendu : <b>${esc(bf.best.nom)}</b> — ${bf.best.qte} vendu${bf.best.qte>1?'s':''} (${euro(bf.best.ca)})</div></div>`:''}
    <table style="width:100%;border-collapse:collapse;font-size:.88rem">
      <thead><tr style="text-align:left;color:#9a8a82;font-size:.78rem">
        <th style="padding:4px 5px">Produit</th><th style="padding:4px 5px;text-align:right">Vendus</th><th style="padding:4px 5px;text-align:right">CA</th><th style="padding:4px 5px;text-align:right">Marge</th></tr></thead>
      <tbody>
        ${bf.list.map(b=>`<tr style="border-top:1px solid var(--hair)">
          <td style="padding:6px 5px"><b>${esc(b.nom)}</b>${b.coutUnit==null?`<br><button class="btn ghost" style="font-size:.7rem;padding:2px 8px;margin-top:3px" onclick="recForm(null,{nom:${JSON.stringify(b.nom)},grandFormat:true})">+ créer la recette</button>`:''}</td>
          <td style="padding:6px 5px;text-align:right">${b.qte}</td>
          <td style="padding:6px 5px;text-align:right">${euro(b.ca)}</td>
          <td style="padding:6px 5px;text-align:right">${b.marge!=null?`<b style="color:#3f7d52">${euro(b.marge)}</b>${b.tauxMarge!=null?`<br><span style="font-size:.72rem;color:#9a8a82">${b.tauxMarge}%</span>`:''}`:'<span style="color:#c9bfb5">—</span>'}</td></tr>`).join('')}
      </tbody>
      <tfoot><tr style="border-top:2px solid var(--bordeaux);font-weight:600">
        <td style="padding:6px 5px">Total</td><td style="padding:6px 5px;text-align:right">${bf.totQte}</td>
        <td style="padding:6px 5px;text-align:right">${euro(bf.totCA)}</td>
        <td style="padding:6px 5px;text-align:right">${bf.totMarge!=null?euro(bf.totMarge):'—'}</td></tr></tfoot>
    </table>
    ${bf.list.some(b=>b.coutUnit==null)?`<p class="note" style="margin-top:6px;color:#b08a3a">Certaines marges sont indisponibles : crée la recette grand format correspondante (même nom) pour calculer le coût et la marge.</p>`:'<p class="note" style="margin-top:6px">Vendus à l\'unité. Marge = CA réel − coût de revient de la recette.</p>'}
  </div>` : '';
  // Indicateur : coffrets vendus par taille (nombre + CA, meilleur format mis en avant).
  const cof = coffretsParTaille(orders);
  const coffretsBox = cof.totNb>0 ? `<div class="panel" style="margin-bottom:12px">
    <h2>📦 Coffrets vendus par taille</h2>
    ${cof.best?`<div class="banner" style="background:#eef6ef;border-color:#3f7d52;margin:4px 0 10px"><div>🏆 Format le plus vendu : <b>coffret ${cof.best.taille}</b> — ${cof.best.nb} vendu${cof.best.nb>1?'s':''} (${euro(cof.best.ca)})</div></div>`:''}
    <table style="width:100%;border-collapse:collapse;font-size:.9rem">
      <thead><tr style="text-align:left;color:#9a8a82;font-size:.8rem">
        <th style="padding:4px 6px">Format</th><th style="padding:4px 6px;text-align:right">Vendus</th><th style="padding:4px 6px;text-align:right">CA</th><th style="padding:4px 6px;text-align:right">Part</th></tr></thead>
      <tbody>
        ${cof.list.map(c=>`<tr style="border-top:1px solid var(--hair)">
          <td style="padding:6px"><b>Coffret ${c.taille}</b></td>
          <td style="padding:6px;text-align:right">${c.nb}</td>
          <td style="padding:6px;text-align:right">${euro(c.ca)}</td>
          <td style="padding:6px;text-align:right;color:#9a8a82">${cof.totNb>0?Math.round(c.nb/cof.totNb*100):0}%</td></tr>`).join('')}
      </tbody>
      <tfoot><tr style="border-top:2px solid var(--bordeaux);font-weight:600">
        <td style="padding:6px">Total</td><td style="padding:6px;text-align:right">${cof.totNb}</td>
        <td style="padding:6px;text-align:right">${euro(cof.totCA)}</td><td></td></tr></tfoot>
    </table>
    <p class="note" style="margin-top:6px">Coffrets des commandes. Le « format le plus vendu » est classé par nombre de coffrets.</p>
  </div>` : '';
  // Diagnostic de l'écart entre le CA total (toutes commandes) et le CA ventilé par parfum.
  const gap = diagFlavorCAGap(orders, markets, marketMoves);
  const caVentile = A.totals.ca;
  // Écart résiduel = ce que le total ne couvre pas via les catégories connues (pertes, remises, arrondi).
  const expliqué = money2(caVentile + gap.prestation + gap.marchesNonVentiles + gap.sansParfum);
  const residuel = money2(gap.total - expliqué);
  const diagBox = `<details style="margin-bottom:12px"><summary style="cursor:pointer;color:#7a6a62;font-size:.84rem;font-weight:600">🔎 Où va le CA total ?</summary>
    <div class="panel" style="margin-top:8px;font-size:.86rem">
      <div style="display:flex;justify-content:space-between;padding:3px 0"><span>CA total (commandes + marchés)</span><b>${euro(gap.total)}</b></div>
      <div style="display:flex;justify-content:space-between;padding:1px 0;font-size:.78rem;color:#9a8a82"><span>&nbsp;&nbsp;· dont commandes</span><span>${euro(gap.totalCmd)}</span></div>
      <div style="display:flex;justify-content:space-between;padding:1px 0;font-size:.78rem;color:#9a8a82"><span>&nbsp;&nbsp;· dont marchés</span><span>${euro(gap.totalMarches)}</span></div>
      <div style="border-top:1px solid var(--hair);margin:6px 0"></div>
      <div style="display:flex;justify-content:space-between;padding:3px 0;color:#3f7d52"><span>✓ Ventilé sur les parfums</span><b>${euro(caVentile)}</b></div>
      <div style="display:flex;justify-content:space-between;padding:1px 0;font-size:.78rem;color:#9a8a82"><span>&nbsp;&nbsp;· dont commandes</span><span>${euro(A.totals.caCmdVentile||0)}</span></div>
      <div style="display:flex;justify-content:space-between;padding:1px 0;font-size:.78rem;color:#9a8a82"><span>&nbsp;&nbsp;· dont marchés</span><span>${euro(A.totals.caMarcheVentile||0)}</span></div>
      ${gap.pyramides>0?`<div style="display:flex;justify-content:space-between;padding:2px 0;color:#7a4b82;font-size:.82rem"><span>&nbsp;&nbsp;dont pyramides redistribuées</span><b>${euro(gap.pyramides)} (${caVentile>0?Math.round(gap.pyramides/caVentile*100):0}%)</b></div>`:''}
      ${gap.prestation>0?`<div style="display:flex;justify-content:space-between;padding:3px 0;color:#7a6a62"><span>↔ Prestations / services (à part, ${gap._nb.prestation})</span><b>${euro(gap.prestation)}</b></div>`:''}
      ${gap.marchesNonVentiles>0?`<div style="display:flex;justify-content:space-between;padding:3px 0;color:#b3261e"><span>⚠ Marchés sans détail de ventes (${gap._nb.marchesNonVentiles})</span><b>${euro(gap.marchesNonVentiles)}</b></div>`:''}
      ${gap.sansParfum>0?`<div style="display:flex;justify-content:space-between;padding:3px 0"><span>Commandes sans parfum (${gap._nb.sansParfum})</span><b>${euro(gap.sansParfum)}</b></div>`:''}
      ${Math.abs(residuel)>0.5?`<div style="display:flex;justify-content:space-between;padding:3px 0;color:#9a8a82"><span>Écart résiduel (pertes, remises, arrondis)</span><b>${euro(residuel)}</b></div>`:''}
      <div style="border-top:1px solid var(--hair);margin:6px 0"></div>
      <p class="note" style="color:#9a8a82">Le « ventilé sur les parfums » inclut désormais tes commandes (coffrets, événements, vrac, grands formats et migrées) au montant réellement encaissé. Seules les prestations et les marchés non détaillés restent hors du CA par parfum.</p>
      ${gap.marchesNonVentiles>0?`<p class="note" style="color:#b3261e;margin-top:6px">⚠ ${euro(gap.marchesNonVentiles)} de CA sur ${gap._nb.marchesNonVentiles} marché(s) ne sont pas répartis par parfum : il manque le détail des ventes (sorties − retours par parfum). Pour les ventiler, édite ces marchés et renseigne ce que tu as emporté et rapporté pour chaque parfum.</p>`:''}
    </div></details>`;
  const kpis=`<div class="kpi-grid">
    <div class="kpi"><span>CA encaissé (parfums) ${kpiI('ca_encaisse')}</span><b>${euro(A.totals.ca)}</b><span>${qty(A.totals.pieces)} pièces vendues</span></div>
    <div class="kpi lnk" onclick="parfumMargesPopup(false)"><span>Marge brute totale ${INFO_I}</span><b style="color:${A.totals.margeBrute>=0?'#3f7d52':'#b3261e'}">${euro(A.totals.margeBrute)}</b><span>${A.totals.tauxMargeGlobal!=null?A.totals.tauxMargeGlobal+'% de marge':'—'}</span></div>
    <div class="kpi lnk" onclick="parfumMargesPopup(true)"><span>Marge nette estimée ${INFO_I}</span><b style="color:${A.totals.margeNette>=0?'#3f7d52':'#b3261e'}">${euro(A.totals.margeNette)}</b><span>après charges ${s.socialGoods}%</span></div>
    <div class="kpi lnk" onclick="parfumPrixMoyenPopup()"><span>Prix moyen pondéré ${INFO_I}</span><b>${euro(avgP.prix)}</b><span>${avgP.source==='ventes'?'d\'après les ventes':'grille (pas de vente)'}</span></div>
    <div class="kpi lnk" onclick="parfumStockPopup()"><span>Stock immobilisé ${INFO_I}</span><b>${euro(A.totals.valStock)}</b><span>au coût de revient</span></div>
  </div>`;

  // bannière d'incohérence CA : encaissé vs attendu (pièces × prix moyen)
  const ecT=A.totals.ecartTheo, theoT=A.totals.caTheo;
  const incohBanner = (theoT>0 && Math.abs(ecT)>=Math.max(5, theoT*0.05))
    ? `<div class="banner" style="background:${ecT<0?'#fdf3f2':'#fff8ec'};border-color:${ecT<0?'#e5b4ae':'#e8cfa0'}">🔎 <div><b>Écart CA encaissé vs attendu : ${ecT>0?'+':''}${euro(ecT)}</b> (encaissé ${euro(A.totals.ca)} · attendu ${euro(theoT)} au prix moyen ${euro(avgP.prix)}). ${ecT<0?'L\'encaissé est sous l\'attendu : pertes/dons non saisis, remises, ou erreur de caisse.':'Ventes au-dessus du tarif moyen, ou grille de prix à réajuster.'}</div></div>`
    : '';

  // alertes hausse de coût
  const hikeBanner = hikes.length?`<div class="banner" style="background:#fdf3f2;border-color:#e5b4ae">📈 <div><b>Hausse de coût matière détectée</b> : ${hikes.slice(0,4).map(h=>`${esc(h.mat)} +${h.varPct}% (impacte ${h.parfums.map(esc).join(', ')})`).join(' · ')}${hikes.length>4?` … +${hikes.length-4}`:''}. Vérifiez les prix de vente des parfums concernés.</div></div>`:'';

  // tableau principal
  const sortBtn=(k,lib)=>`<button class="btn ghost sm" style="${_parfumSort===k?'border-color:var(--caramel);font-weight:600':''}" onclick="_parfumSort='${k}';renderParfums()">${lib}</button>`;
  const mainTable=`<div style="display:flex;flex-direction:column;gap:10px">${rows.map(r=>{
      const taux=r.tauxMarge;
      const tauxClamp=taux!=null?Math.max(0,Math.min(100,taux)):0;
      const col=(typeof flavorColor==='function')?flavorColor(r.nom):'#ccc';
      return `<div onclick="parfumDetail(${r.recipeId})" style="cursor:pointer;background:#fff;border:1px solid var(--hair);border-left:4px solid ${r.scale.col};border-radius:14px;padding:13px 15px;box-shadow:var(--sh-1)">
        <div style="display:flex;align-items:center;gap:9px;margin-bottom:10px">
          <span style="width:20px;height:20px;border-radius:50%;background:${col};flex:none;box-shadow:inset 0 0 0 1px rgba(0,0,0,.08)"></span>
          <b style="flex:1;font-size:1rem;color:var(--bordeaux);overflow:hidden;text-overflow:ellipsis;white-space:nowrap">${esc(r.nom)}${r.cost.pertePct>0?` <span style="color:#9a8a82;font-size:.7rem;font-weight:400">· pertes ${r.cost.pertePct}%</span>`:''}</b>
          <span class="tag" style="background:${r.scale.col};color:#fff;font-size:.66rem">${r.scale.dot} ${r.scale.label||''}</span>
        </div>
        <div style="display:flex;gap:6px;text-align:center;margin-bottom:10px">
          <div style="flex:1"><div style="font-size:.6rem;text-transform:uppercase;letter-spacing:.03em;color:#9a8a82;font-weight:600">Coût/pc</div><div style="font-weight:700;color:var(--bordeaux);font-size:.88rem">${euro(r.cost.coutRevientUnit)}</div></div>
          <div style="flex:1;border-left:1px solid var(--hair)"><div style="font-size:.6rem;text-transform:uppercase;letter-spacing:.03em;color:#9a8a82;font-weight:600">Vente/pc</div><div style="font-weight:700;color:var(--bordeaux);font-size:.88rem">${r.prixVenteMoyen!=null?euro(r.prixVenteMoyen):'—'}</div></div>
          <div style="flex:1;border-left:1px solid var(--hair)"><div style="font-size:.6rem;text-transform:uppercase;letter-spacing:.03em;color:#9a8a82;font-weight:600">Vendus</div><div style="font-weight:700;color:var(--bordeaux);font-size:.88rem">${r.piecesVendues>0?qty(r.piecesVendues):'0'}</div></div>
          <div style="flex:1;border-left:1px solid var(--hair)"><div style="font-size:.6rem;text-transform:uppercase;letter-spacing:.03em;color:#9a8a82;font-weight:600">Marge brute</div><div style="font-weight:700;font-size:.88rem;color:${r.margeBrute>=0?'#3f7d52':'#b3261e'}">${euro(r.margeBrute)}</div></div>
        </div>
        <div style="display:flex;align-items:center;gap:8px">
          <span style="font-size:.66rem;color:#9a8a82;flex:none">taux net</span>
          <div style="flex:1;height:8px;background:#f0e9de;border-radius:5px;overflow:hidden"><div style="width:${tauxClamp}%;height:100%;background:${r.scale.col}"></div></div>
          <span style="font-size:.78rem;font-weight:700;color:${r.scale.col};flex:none">${taux!=null?taux+'%':'—'}</span>
        </div>
      </div>`;
    }).join('')}</div>
    <p class="note">Touchez une carte pour le détail (coque/garniture, simulation de prix, seuil de rentabilité). Base de calcul = <b>CA encaissé</b> réel (commandes + marchés), réparti par parfum selon les pièces vendues. Coût de revient = matières (prix courant) + pertes + consommables${s.laborEnabled?' + main-d\'œuvre':''}.</p>`;

  // parfums sans recette (vendus mais non rattachés)
  const unmatchedBlock=A.unmatched.length?`<div class="panel"><h2>Parfums vendus sans recette <span class="tag warn">${A.unmatched.length}</span></h2>
     <p class="note">Ces parfums apparaissent dans les ventes mais n'ont pas de recette correspondante — impossible de calculer leur coût/marge. <b>Touche un parfum pour créer sa recette</b> (le nom est pré-rempli) :</p>
     <div style="display:flex;flex-wrap:wrap;gap:6px;margin-top:8px">
       ${A.unmatched.map(u=>`<button class="btn ghost sm" onclick="recForm(null,{nom:${JSON.stringify(u.nom)}})">+ ${esc(u.nom)} <span style="color:#9a8a82">(${qty(u.piecesVendues+u.piecesDon)} pc)</span></button>`).join('')}
     </div>
     <button class="btn ghost sm" style="margin-top:10px" onclick="fixFlavorTypos()">🔤 Corriger les doublons d'orthographe</button>
     <p class="note" style="margin-top:4px;font-size:.78rem;color:#9a8a82">Certains de ces noms sont peut-être de simples fautes de frappe (ex : Raffaello vs Rafaello). Ce bouton les uniformise sur tes parfums officiels.</p></div>`:'';

  // Pareto
  const paretoBlock = sold.length?`<div class="panel"><h2>Analyse Pareto 80/20</h2>
     ${seuil80?`<div class="banner"><div><b>${seuil80} parfum(s)</b> sur ${sold.length} génèrent <b>80%</b> de votre marge brute. Concentrez vos efforts (appro, mise en avant, production) sur eux.</div></div>`:''}
     <div class="table-wrap"><table><thead><tr><th>#</th><th>Parfum</th><th>Marge brute</th><th>% cumulé</th></tr></thead><tbody>
       ${pareto.map((r,i)=>`<tr${seuil80&&i<seuil80?' style="background:#f3f8f4"':''}><td>${i+1}</td><td><b>${esc(r.nom)}</b></td><td>${euro(r.margeBrute)}</td>
         <td><span class="tag ${r.cumPct<=80?'ok':''}">${r.cumPct.toFixed(0)}%</span></td></tr>`).join('')}
     </tbody></table></div></div>`:'';

  // classements
  const rankBlock=`<div class="panel"><h2>Classement par rentabilité</h2>
     <div class="row2">
       <div><h3 style="font-size:.92rem;margin:6px 0;color:#3f7d52">🟢 Les plus rentables</h3>
         ${best.length?best.map(r=>`<div class="sum-box"><span>${esc(r.nom)}</span><b style="color:#3f7d52">${r.tauxMarge}% · ${euro(r.margeUnit||0)}/pc</b></div>`).join(''):'<p class="note">—</p>'}</div>
       <div><h3 style="font-size:.92rem;margin:6px 0;color:#b3261e">🔴 Les moins rentables</h3>
         ${worst.length?worst.map(r=>`<div class="sum-box"><span>${esc(r.nom)}</span><b style="color:${r.tauxMarge<0?'#b3261e':'#d98324'}">${r.tauxMarge}% · ${euro(r.margeUnit||0)}/pc</b></div>`).join(''):'<p class="note">—</p>'}</div>
     </div></div>`;

  // recommandations
  const recBlock=`<div class="panel"><h2>Recommandations intelligentes</h2>
     ${recs.map(r=>`<div class="sum-box" style="align-items:flex-start"><span style="font-size:1.1rem">${r.icon}</span><b style="font-weight:500;color:${r.col};text-align:left;flex:1;margin-left:8px">${r.txt}</b></div>`).join('')}</div>`;

  // évolution de la rentabilité dans le temps (marge brute mensuelle, par CA - coût des ventes)
  const evolBlock = await buildFlavorEvolutionBlock(data, A);

  // outils de prévision
  const prevBlock=`<div class="panel"><h2>Prévisions & aide à la décision</h2>
     <div class="flex" style="gap:8px;flex-wrap:wrap">
       <button class="btn ghost sm" onclick="parfumBatchSim()">🧮 Marge prévisionnelle d'un batch</button>
       <button class="btn ghost sm" onclick="parfumMixOptim()">🎯 Mix de parfums optimal</button>
       <button class="btn ghost sm" onclick="parfumMarketGain()">⛺ Gain estimé d'un marché</button>
     </div>
     <p class="note">Calculs basés sur vos coûts de revient et l'historique de vente. Aucune donnée ne quitte l'appareil.</p></div>`;

  document.getElementById('main').innerHTML=`
   <div class="topbar"><div><h1>Rentabilité parfums</h1><p>Coûts de revient, marges & recommandations par parfum</p></div>
     <button class="btn ghost sm" onclick="parfumSettingsForm()">⚙ Coûts & MO</button></div>
   ${hikeBanner}
   ${incohBanner}
   ${diagBox}
   ${kpis}
   ${coffretsBox}
   ${bigBox}
   <div class="panel"><h2>Synthèse par parfum</h2>
     <div class="flex" style="gap:6px;flex-wrap:wrap;margin-bottom:8px"><span style="font-size:.8rem;color:#9a8a82;align-self:center">Trier :</span>
       ${sortBtn('marge','Marge')} ${sortBtn('ca','CA')} ${sortBtn('pieces','Volume')} ${sortBtn('taux','Taux')} ${sortBtn('stock','Stock')} ${sortBtn('nom','A→Z')}</div>
     ${mainTable}</div>
   ${unmatchedBlock}
   ${recBlock}
   ${paretoBlock}
   ${rankBlock}
   ${evolBlock}
   ${prevBlock}`;

  // dessine la courbe d'évolution si présente
  drawFlavorEvolutionChart(data, A);
}

// Bloc HTML pour l'évolution mensuelle de la marge (placeholder de conteneur).
async function buildFlavorEvolutionBlock(data, A){
  return `<div class="panel"><h2>Évolution de la rentabilité <span style="font-weight:400;font-size:.8rem;color:#9a8a82">— marge brute mensuelle</span></h2>
     <div id="flavorEvolChart"></div>
     <p class="note">CA mensuel (commandes + marchés clos) − coût de revient des pièces vendues le mois.</p></div>`;
}

// Calcule et dessine la courbe d'évolution (CA, coût, marge) par mois.
function drawFlavorEvolutionChart(data, A){
  const el=document.getElementById('flavorEvolChart'); if(!el) return;
  const {recipes, recipeItems, lots, orders, markets, marketMoves, productions, settings}=data;
  const s=settings||getSettings();
  const costByRecipe=A.costByRecipe;
  const units=Object.values(costByRecipe).map(c=>c.coutRevientUnit).filter(x=>x>0);
  const avgUnit=units.length?units.reduce((a,b)=>a+b,0)/units.length:0;
  // retrouver la recette d'un parfum/mouvement
  const recByNorm={}; recipes.forEach(r=>{recByNorm[aiNormalize(r.produitNom)]=r;});
  const prodById={}; (productions||[]).forEach(p=>{prodById[p.id]=p;});
  const recName=rid=>(recipes.find(r=>r.id===rid)||{}).produitNom||'';
  const unitCostForParfum=nom=>{ const r=recByNorm[aiNormalize(nom)]; return r&&costByRecipe[r.id]?costByRecipe[r.id].coutRevientUnit:avgUnit; };
  const moveParfum=m=>{ if(m.parfum) return m.parfum; if(m.productionId!=null && prodById[m.productionId]) return recName(prodById[m.productionId].recipeId)||''; return ''; };

  // pièces vendues par mois + CA par mois (commandes)
  const caByMonth={}, coutByMonth={};
  (orders||[]).forEach(o=>{
    const k=ymKey(o.date); if(!k) return;
    caByMonth[k]=money2((caByMonth[k]||0)+(+o.montant||0));
    // pièces de la commande × coût moyen (approche globale mensuelle)
    const lignes=orderToLines(o);
    let pieces=0;
    lignes.forEach(ln=>{
      if(ln.type==='coffret') pieces+=+ln.taille||0;
      else if(ln.type==='don') pieces+=(ln.parfums||[]).reduce((a,p)=>a+(+p.qte||0),0);
      else if(ln.type==='evenement') pieces+=+ln.evQte||0;
      else if(ln.type==='grand') pieces+=(ln.items||[]).reduce((a,p)=>a+(+p.qte||0),0);
    });
    coutByMonth[k]=money2((coutByMonth[k]||0)+pieces*avgUnit);
  });
  // marchés clos : CA = ENCAISSÉ (base de calcul) ; coût = pièces × coût DU PARFUM
  const movesByMk={}; (marketMoves||[]).forEach(mv=>{(movesByMk[mv.marketId] ||= []).push(mv);});
  (markets||[]).filter(mk=>mk.statut==='clos').forEach(mk=>{
    const k=ymKey(mk.date); if(!k) return;
    const ca=mk.ca||{}; caByMonth[k]=money2((caByMonth[k]||0)+marketNetCA(mk));
    const mv=movesByMk[mk.id]||[];
    const byParfum={};
    mv.forEach(m=>{ const nom=moveParfum(m)||'(parfum ?)'; const b=(byParfum[nom] ||= {sortie:0,retour:0,don:0,perte:0});
      if(m.type==='sortie')b.sortie+=+m.qte||0; else if(m.type==='retour')b.retour+=+m.qte||0; else if(m.type==='don')b.don+=+m.qte||0; else if(m.type==='perte')b.perte+=+m.qte||0; });
    let coutMk=0;
    Object.keys(byParfum).forEach(nom=>{ const b=byParfum[nom]; const v=Math.max(0,b.sortie-b.retour-b.don-b.perte); if(v<=0) return;
      coutMk=money2(coutMk+v*unitCostForParfum(nom)); });
    coutByMonth[k]=money2((coutByMonth[k]||0)+coutMk);
  });
  const keys=[...new Set([...Object.keys(caByMonth),...Object.keys(coutByMonth)])].sort().slice(-12);
  if(!keys.length){ el.innerHTML='<div class="empty">Pas encore de ventes datées pour tracer la courbe.</div>'; return; }
  const sCA={label:'CA', color:'#3f7d52', points:keys.map(k=>({x:k,y:caByMonth[k]||0}))};
  const sCout={label:'Coût de revient', color:'#b04a3e', points:keys.map(k=>({x:k,y:coutByMonth[k]||0}))};
  const sMarge={label:'Marge brute', color:'#AA7C39', points:keys.map(k=>({x:k,y:money2((caByMonth[k]||0)-(coutByMonth[k]||0))}))};
  el.innerHTML=lineChart([sCA,sCout,sMarge],{fmt:v=>euro(v),xlabel:ymLabel,zero:true});
}

// DÉTAIL d'un parfum : ventilation coque/garniture, coût détaillé, simulation de prix, seuil de rentabilité.
// Barre décomposée propre à la rentabilité par parfum : à partir du prix de vente,
// montre visuellement la part de chaque coût (matières, main-d'œuvre, charges) et la marge restante.
function parfumMargeBar(row, c){
  if(privacyModeEnabled()) return '';
  const prix = row.prixVenteMoyen;
  if(prix==null || prix<=0) return ''; // pas de vente → pas de décomposition pertinente
  const mat = (c.coutMatUnit||0) + (c.coutConsoUnit||0); // matières + consommables
  const mo  = c.coutMODUnit||0;                           // main-d'œuvre
  const charges = row.chargesSoc!=null ? row.chargesSoc : 0; // charges sociales / pièce
  const marge = Math.max(0, prix - mat - mo - charges);      // ce qu'il reste vraiment
  const segs=[
    {lbl:'Matières', v:mat, col:'#b3261e'},
    {lbl:'Main-d\'œuvre', v:mo, col:'#d98324'},
    {lbl:'Charges', v:charges, col:'#c9a227'},
    {lbl:'Marge nette', v:marge, col:'#3f7d52'}
  ].filter(s=>s.v>0);
  const pct=v=> prix>0 ? Math.round(v/prix*100) : 0;
  const barre2 = segs.map(s=>`<div style="width:${Math.max(2,s.v/prix*100)}%;background:${s.col}" title="${s.lbl} : ${euro(s.v)}"></div>`).join('');
  const legende = segs.map(s=>`<span style="display:inline-flex;align-items:center;gap:4px;font-size:.72rem;color:#6a5a52">
      <span style="width:10px;height:10px;border-radius:2px;background:${s.col};display:inline-block"></span>${s.lbl} ${euro(s.v)} <span style="color:#9a8a82">(${pct(s.v)}%)</span></span>`).join('');
  return `<div style="background:#fcfaf6;border:1px solid var(--hair);border-radius:12px;padding:11px 13px;margin-bottom:12px">
    <div style="font-size:.78rem;color:#7a6a62;margin-bottom:6px">Sur <b>${euro(prix)}</b> de prix de vente, voici où va chaque centime :</div>
    <div style="display:flex;height:22px;border-radius:6px;overflow:hidden;background:#eee">${barre2}</div>
    <div style="display:flex;flex-wrap:wrap;gap:10px;margin-top:8px">${legende}</div>
  </div>`;
}
